"use client";

import { useEffect, useState } from "react";
import { AppShell } from "@/components/app-shell";
import { SharedPost } from "@/components/shared-post";

export default function SharedPostPage() {
  const [postId, setPostId] = useState("");
  useEffect(() => setPostId(new URLSearchParams(window.location.search).get("postId") ?? ""), []);

  return <AppShell title="Publicação">{postId ? <SharedPost postId={postId} /> : <p>Publicação não informada.</p>}</AppShell>;
}

