"use client";

import { useEffect, useState } from "react";
import { AppShell } from "@/components/app-shell";
import { PublicPetProfile } from "@/components/public-pet-profile";

export default function PetProfilePage() {
  const [petId, setPetId] = useState("");
  useEffect(() => setPetId(new URLSearchParams(window.location.search).get("petId") ?? ""), []);

  return <AppShell title="Perfil do animal">{petId ? <PublicPetProfile petId={petId} /> : <p>Perfil do animal não informado.</p>}</AppShell>;
}

import Link from "next/link";
import { ArrowLeft, Heart, MapPin, ShieldCheck } from "lucide-react";

export default function SafetyPage() {
  return <main className="trust-document-page"><Link className="wordmark trust-doc-brand" href="/"><span className="wordmark-icon"><Heart size={16}/></span><span>match<span>animal</span></span></Link><Link href="/dashboard" className="back-link"><ArrowLeft size={14}/> Voltar</Link><div className="document-kicker"><ShieldCheck size={14}/> CONEXÕES RESPONSÁVEIS</div><h1>Segurança começa no cuidado.</h1><p className="document-intro">Alguns princípios que guiam o MatchAnimal enquanto os recursos completos de segurança são construídos.</p><div className="document-sections"><section><h2>Proteja sua localização</h2><p>O perfil mostra cidade e estado como referência ampla. Nunca compartilhe seu endereço residencial publicamente; combine o primeiro encontro em um local movimentado e apropriado para os pets.</p></section><section><h2>Converse antes de se encontrar</h2><p>Conversem sobre rotina, temperamento, vacinação e necessidades do animal. As informações do perfil são declaradas pelo tutor e devem ser confirmadas diretamente.</p></section><section><h2>Encontros de reprodução</h2><p>Uma pontuação de compatibilidade não avalia saúde. Reprodução exige verificação documental, orientação veterinária, bem-estar dos animais e decisão informada dos responsáveis. Não há recomendação automática.</p></section><section><h2>Adoção é uma candidatura</h2><p>O interesse em adoção segue um processo próprio de candidatura e avaliação pelo responsável, sem curtidas mútuas. Evite enviar dados financeiros ou documentos pessoais a perfis desconhecidos.</p></section><section><h2>Bloqueio, denúncia e moderação</h2><p>A base já prevê registros de bloqueio e denúncias, e fotos/publicações têm status de moderação. Os controles de usuário e o atendimento de denúncias ainda serão conectados antes de uma operação pública.</p></section></div><p className="document-date">Se houver perigo imediato, procure os serviços locais de emergência e proteção animal.</p></main>;
}

"use client";

import { useCallback, useEffect, useState } from "react";
import { ArrowUpRight, BadgeCheck, Building2, CreditCard, Heart, MapPin, PawPrint, RefreshCw, Search, ShieldAlert, Store, Users, UserRound } from "lucide-react";
import { ModerationPanel } from "@/components/moderation-panel";

type Overview = {
  metrics: { users: number; newUsersLast30Days: number; activePets: number; publicPets: number; activeMatches: number; openReports: number; publicPosts: number; partners: number };
  partners: Array<{ id: string; type: string; createdAt: string; displayName: string; city: string | null; state: string | null; pets: number }>;
  recentAccounts: Array<{ id: string; type: string; createdAt: string; displayName: string; city: string | null; state: string | null; pets: number }>;
  billing: { provider: "stripe"; configured: boolean; priceConfigured: boolean };
};

const api = process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:4000";
const number = new Intl.NumberFormat("pt-BR");
const accountLabels: Record<string, string> = { ORGANIZATION: "ONG / organização", PROTECTOR: "Protetor", PROFESSIONAL: "Profissional" };

export function AdminPanel() {
  const [data, setData] = useState<Overview | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [section, setSection] = useState<"overview" | "accounts" | "partners" | "billing" | "moderation">("overview");
  const [accountSearch, setAccountSearch] = useState("");
  const [accountType, setAccountType] = useState("ALL");
  const [partnerSearch, setPartnerSearch] = useState("");
  const load = useCallback(async () => {
    setLoading(true);
    try {
      const response = await fetch(`${api}/api/safety/admin/overview`, { credentials: "include" });
      const result = await response.json();
      if (!response.ok) throw new Error(result.message ?? "Não foi possível carregar os indicadores.");
      setData(result as Overview); setError("");
    } catch (cause) { setError((cause as Error).message); }
    finally { setLoading(false); }
  }, []);
  useEffect(() => { void load(); }, [load]);

  const tabs = [
    { id: "overview", label: "Visão geral", icon: ArrowUpRight },
    { id: "accounts", label: "Contas", icon: Users },
    { id: "partners", label: "Parceiros", icon: Store },
    { id: "billing", label: "Planos e cobrança", icon: CreditCard },
    { id: "moderation", label: "Moderação", icon: ShieldAlert },
  ] as const;

  return <section className="admin-panel">
    <header className="admin-heading"><div><div className="product-eyebrow"><span><PawPrint size={13}/></span> CENTRAL DE OPERAÇÕES</div><h1 className="product-h1">MatchAnimal <em>por dentro.</em></h1><p className="product-lead">Acompanhe a comunidade, os parceiros e a estrutura de monetização.</p></div><button className="admin-refresh" onClick={() => void load()} disabled={loading}><RefreshCw size={14}/> Atualizar</button></header>
    <nav className="admin-tabs" aria-label="Seções administrativas">{tabs.map(({ id, label, icon: Icon }) => <button key={id} className={section === id ? "admin-tab-active" : ""} onClick={() => setSection(id)}><Icon size={15}/>{label}{id === "moderation" && data?.metrics.openReports ? <i>{data.metrics.openReports}</i> : null}</button>)}</nav>
    {error && <p className="settings-error" role="alert">{error}</p>}
    {loading && !data ? <div className="profile-loading"><span className="session-spinner"/> Carregando dados administrativos…</div> : null}
    {data && section === "overview" && <>
      <div className="admin-kpis">
        <Metric icon={Users} label="Contas" value={data.metrics.users} note={`+${number.format(data.metrics.newUsersLast30Days)} nos últimos 30 dias`} />
        <Metric icon={PawPrint} label="Animais ativos" value={data.metrics.activePets} note={`${number.format(data.metrics.publicPets)} perfis públicos`} />
        <Metric icon={Heart} label="Conexões" value={data.metrics.activeMatches} note="Matches ativos" />
        <Metric icon={ShieldAlert} label="Denúncias abertas" value={data.metrics.openReports} note="Aguardando análise" alert={data.metrics.openReports > 0} />
      </div>
      <div className="admin-overview-grid"><article className="admin-card"><div className="admin-card-title"><div><span className="admin-card-icon"><Store size={16}/></span><h2>Rede de parceiros</h2></div><button onClick={() => setSection("partners")}>Ver parceiros <ArrowUpRight size={13}/></button></div><p>ONGs, protetores e profissionais cadastrados na comunidade.</p><strong className="admin-big-number">{number.format(data.metrics.partners)}</strong><small>contas parceiras</small></article>
        <article className="admin-card"><div className="admin-card-title"><div><span className="admin-card-icon"><CreditCard size={16}/></span><h2>Stripe</h2></div><button onClick={() => setSection("billing")}>Configurar <ArrowUpRight size={13}/></button></div><p>Preparação da integração de checkout e planos recorrentes.</p><span className={`billing-status ${data.billing.configured ? "billing-ready" : "billing-pending"}`}><i/>{data.billing.configured ? "Credenciais detectadas" : "Aguardando conexão da conta"}</span><small>{data.billing.priceConfigured ? "Preço Stripe detectado" : "Nenhum Price ID configurado"}</small></article></div>
      <div className="admin-quick-stats"><span><BadgeCheck size={15}/> {number.format(data.metrics.publicPosts)} publicações públicas</span><span><MapPin size={15}/> operação por parceiros locais</span></div>
    </>}
    {data && section === "accounts" && <section className="admin-card admin-partners"><div className="admin-card-title"><div><span className="admin-card-icon"><Users size={16}/></span><h2>Contas recentes</h2></div><span className="admin-count">Exibindo até 100</span></div><p>Visão operacional das contas cadastradas. Dados de contato e credenciais ficam protegidos.</p><div className="admin-filters"><label className="admin-search"><Search size={14}/><input aria-label="Buscar conta" placeholder="Buscar por nome ou cidade" value={accountSearch} onChange={(event) => setAccountSearch(event.target.value)}/></label><select aria-label="Filtrar tipo de conta" value={accountType} onChange={(event) => setAccountType(event.target.value)}><option value="ALL">Todos os perfis</option><option value="TUTOR">Tutores</option><option value="ORGANIZATION">ONGs e organizações</option><option value="PROTECTOR">Protetores</option><option value="PROFESSIONAL">Profissionais</option></select></div><AccountTable accounts={data.recentAccounts.filter((account) => (accountType === "ALL" || account.type === accountType) && `${account.displayName} ${account.city ?? ""} ${account.state ?? ""}`.toLocaleLowerCase("pt-BR").includes(accountSearch.toLocaleLowerCase("pt-BR")))}/></section>}
    {data && section === "partners" && <section className="admin-card admin-partners"><div className="admin-card-title"><div><span className="admin-card-icon"><Store size={16}/></span><h2>Parceiros da comunidade</h2></div><span className="admin-count">{number.format(data.metrics.partners)} no total</span></div><p>Contas de organizações, protetores e profissionais. Localização exibida apenas em nível de cidade.</p><div className="admin-filters"><label className="admin-search"><Search size={14}/><input aria-label="Buscar parceiro" placeholder="Buscar parceiro ou cidade" value={partnerSearch} onChange={(event) => setPartnerSearch(event.target.value)}/></label></div><AccountTable accounts={data.partners.filter((partner) => `${partner.displayName} ${partner.city ?? ""} ${partner.state ?? ""} ${accountLabels[partner.type] ?? partner.type}`.toLocaleLowerCase("pt-BR").includes(partnerSearch.toLocaleLowerCase("pt-BR")))}/></section>}
    {data && section === "billing" && <div className="billing-layout"><article className="admin-card billing-main"><div className="billing-brand"><span className="stripe-mark">S</span><div><h2>Pagamentos com Stripe</h2><p>Base de cobrança para planos e recursos comerciais do MatchAnimal.</p></div></div><span className={`billing-status ${data.billing.configured ? "billing-ready" : "billing-pending"}`}><i/>{data.billing.configured ? "Credenciais do servidor configuradas" : "Conexão pendente"}</span><div className="billing-checklist"><h3>Próximos passos da integração</h3><ol><li><span>1</span><div><strong>Conectar a conta Stripe ao ambiente de produção</strong><small>Comece em modo de teste e mantenha as chaves secretas exclusivamente no backend.</small></div></li><li><span>2</span><div><strong>Cadastrar os produtos e planos</strong><small>Defina planos para parceiros e recursos premium antes de ativar o checkout.</small></div></li><li><span>3</span><div><strong>Receber eventos pelo webhook</strong><small>O webhook precisa sincronizar pagamentos, cancelamentos e renovações com o app.</small></div></li></ol></div><div className="billing-note"><ShieldAlert size={15}/><p>O Stripe ainda não está conectado. Checkout, assinatura e receita continuam inativos até a API e os webhooks serem implementados e validados.</p></div><a className="stripe-dashboard-link" href="https://dashboard.stripe.com/test/apikeys" target="_blank" rel="noreferrer">Abrir painel Stripe em modo de teste <ArrowUpRight size={14}/></a></article><aside className="admin-card billing-plan-card"><span className="admin-card-icon"><Heart size={16}/></span><h2>Modelo comercial recomendado</h2><ul><li><strong>Gratuito:</strong> perfil, adoção, segurança e conexões essenciais.</li><li><strong>Planos para parceiros:</strong> ferramentas de divulgação e gestão para ONGs e profissionais.</li><li><strong>Recursos premium:</strong> conveniência e descoberta avançada, sem cobrar por segurança ou bem-estar.</li></ul><small>Os preços e limites ficam pendentes de decisão do produto.</small></aside></div>}
    {section === "moderation" && <ModerationPanel/>}
  </section>;
}

function Metric({ icon: Icon, label, value, note, alert = false }: { icon: typeof Users; label: string; value: number; note: string; alert?: boolean }) {
  return <article className={`admin-metric ${alert ? "admin-metric-alert" : ""}`}><span className="admin-metric-icon"><Icon size={17}/></span><span className="admin-metric-label">{label}</span><strong>{number.format(value)}</strong><small>{note}</small></article>;
}

function AccountTable({ accounts }: { accounts: Overview["recentAccounts"] }) {
  if (!accounts.length) return <div className="admin-empty"><UserRound size={23}/><strong>Nenhuma conta encontrada</strong><span>Ajuste a busca ou os filtros para ver outros perfis.</span></div>;
  return <div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Perfil</th><th>Tipo</th><th>Localização</th><th>Animais</th><th>Cadastro</th></tr></thead><tbody>{accounts.map((account) => <tr key={account.id}><td><span className="table-person"><i><UserRound size={14}/></i><strong>{account.displayName}</strong></span></td><td><span className="account-type-pill">{accountLabels[account.type] ?? "Tutor"}</span></td><td>{[account.city, account.state].filter(Boolean).join(" / ") || "—"}</td><td>{account.pets}</td><td>{new Intl.DateTimeFormat("pt-BR", { dateStyle: "medium" }).format(new Date(account.createdAt))}</td></tr>)}</tbody></table></div>;
}

