"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { Check, HeartHandshake, LoaderCircle, PawPrint, X } from "lucide-react";

type Application = { id: string; petId: string; status: string; message: string; livingDetails: string | null; createdAt: string; isMine: boolean; pet: { name: string; intent: string }; applicant: { tutor: { displayName: string; city: string | null; state: string | null } | null } };
const api = process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:4000";
const statusText: Record<string, string> = { SUBMITTED: "Recebida", IN_REVIEW: "Em análise", APPROVED: "Aprovada", DECLINED: "Encerrada", WITHDRAWN: "Retirada" };

export function AdoptionCenter() {
  const [items, setItems] = useState<Application[]>([]); const [loading, setLoading] = useState(true); const [busy, setBusy] = useState(""); const [error, setError] = useState("");
  async function load() { setLoading(true); setError(""); try { const response = await fetch(`${api}/api/pets/adoption-applications`, { credentials: "include" }); const result = await response.json(); if (!response.ok) throw new Error(result.message ?? "Não foi possível carregar as candidaturas."); setItems(result as Application[]); } catch (cause) { setError((cause as Error).message); } finally { setLoading(false); } }
  useEffect(() => { void load(); }, []);
  async function action(item: Application, decision: "APPROVED" | "DECLINED" | "WITHDRAWN") { setBusy(item.id); setError(""); try { const path = decision === "WITHDRAWN" ? `/api/pets/adoption-applications/${item.id}/withdraw` : `/api/pets/adoption-applications/${item.id}`; const response = await fetch(`${api}${path}`, { method: decision === "WITHDRAWN" ? "POST" : "PATCH", credentials: "include", headers: { "Content-Type": "application/json" }, ...(decision === "WITHDRAWN" ? {} : { body: JSON.stringify({ status: decision }) }) }); const result = await response.json(); if (!response.ok) throw new Error(result.message ?? "Não foi possível atualizar a candidatura."); await load(); } catch (cause) { setError((cause as Error).message); } finally { setBusy(""); } }
  if (loading) return <div className="profile-loading"><span className="session-spinner"/> Carregando candidaturas…</div>;
  return <section className="adoption-center"><header><div className="product-eyebrow"><span><HeartHandshake size={13}/></span> ENCONTROS QUE PODEM MUDAR UMA VIDA</div><h1 className="product-h1">Adoções com <em>responsabilidade.</em></h1><p className="product-lead">Acompanhe as candidaturas que você enviou e as recebidas pelos seus animais.</p></header>{error&&<p className="settings-error" role="alert">{error}</p>}{items.length?<div className="adoption-list">{items.map((item)=><article key={item.id} className="adoption-card"><div className="adoption-card-heading"><span><PawPrint size={17}/></span><div><h2>{item.isMine?`Sua candidatura para ${item.pet.name}`:`Candidatura para ${item.pet.name}`}</h2><small>{item.isMine?"Enviada":"De "+(item.applicant.tutor?.displayName??"tutor")}{item.applicant.tutor?.city?` · ${item.applicant.tutor.city}, ${item.applicant.tutor.state??""}`:""} · {new Intl.DateTimeFormat("pt-BR",{dateStyle:"medium"}).format(new Date(item.createdAt))}</small></div><b className={`adoption-status adoption-${item.status.toLowerCase()}`}>{statusText[item.status]??item.status}</b></div><div className="adoption-message"><strong>Mensagem</strong><p>{item.message}</p>{item.livingDetails&&<><strong>Sobre o lar</strong><p>{item.livingDetails}</p></>}</div>{item.status==="SUBMITTED"&&<footer>{item.isMine?<button disabled={busy===item.id} onClick={()=>void action(item,"WITHDRAWN")}>Retirar candidatura</button>:<><button className="adoption-approve" disabled={busy===item.id} onClick={()=>void action(item,"APPROVED")}>{busy===item.id?<LoaderCircle size={13}/>:<Check size={13}/>} Aprovar e concluir adoção</button><button disabled={busy===item.id} onClick={()=>void action(item,"DECLINED")}><X size={13}/> Encerrar candidatura</button></>}</footer>}</article>)}</div>:<div className="adoption-empty"><PawPrint size={25}/><h2>Ainda não há candidaturas</h2><p>Quando alguém se candidatar a um animal seu, ou quando você enviar uma candidatura, ela aparecerá aqui.</p><Link href="/explorar">Explorar animais para adoção</Link></div>}</section>;
}

"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { Bell, Bird, Cat, Dog, Heart, LogOut, MapPin, MessageCircle, PawPrint, Search, ShieldAlert } from "lucide-react";
import { createContext, useContext, useEffect, useState } from "react";
import { Button } from "@/components/ui/button";
import { Dialog } from "@/components/ui/dialog";

type Session = { accountInfo: { displayName: string; city: string; state: string }; matchCount: number; unreadCount: number };
const SessionContext = createContext<Session | null>(null);
export function useAppSession() { return useContext(SessionContext); }

const primaryLinks = [
  { href: "/dashboard", label: "Início", icon: Dog },
  { href: "/explorar", label: "Explorar", icon: PawPrint },
  { href: "/matches", label: "Conexões", icon: Heart },
  { href: "/comunidade", label: "Comunidade", icon: Bird },
  { href: "/configuracoes", label: "Perfil", icon: Cat },
];
const routeMatches = (href: string, pathname: string) => pathname === href || pathname === `${href}/`
  || (href === "/matches" && pathname.startsWith("/mensagens"))
  || (href === "/explorar" && pathname.startsWith("/pet/perfil"))
  || (href === "/comunidade" && ["/comunidade", "/grupos", "/eventos"].some((path) => pathname.startsWith(path)))
  || (href === "/configuracoes" && (pathname.startsWith("/configuracoes") || pathname.startsWith("/animais")));

export function AppShell({ children, title }: { children: React.ReactNode; title: string }) {
  const pathname = usePathname();
  const [authReady, setAuthReady] = useState(false);
  const [accountInfo, setAccountInfo] = useState<{ displayName: string; city: string; state: string }>({ displayName: "Seu perfil", city: "", state: "" });
  const [isModerator, setIsModerator] = useState(false);
  const [unreadNotifications, setUnreadNotifications] = useState(0);
  const [matchCount, setMatchCount] = useState(0);
  const [authError, setAuthError] = useState("");
  const [attempt, setAttempt] = useState(0);
  const [searchOpen, setSearchOpen] = useState(false);

  useEffect(() => {
    const api = process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:4000";
    let active = true;
    async function verifySession() {
      setAuthError("");
      try {
        let response = await fetch(`${api}/api/auth/me`, { credentials: "include" });
        if (response.status === 401) {
          const refreshed = await fetch(`${api}/api/auth/refresh`, { method: "POST", credentials: "include" });
          if (refreshed.ok) response = await fetch(`${api}/api/auth/me`, { credentials: "include" });
        }
        if (!active) return;
        if (response.status === 401) { window.location.replace("/entrar"); return; }
        if (!response.ok) throw new Error("Conta indisponível");
        const account = await response.json() as { isModerator?: boolean; tutor?: { displayName?: string | null; city?: string | null; state?: string | null } | null };
        setIsModerator(Boolean(account.isModerator));
        setAccountInfo({ displayName: account.tutor?.displayName?.trim() || "Seu perfil", city: account.tutor?.city?.trim() || "", state: account.tutor?.state?.trim() || "" });
        setAuthReady(true);
      } catch { if (active) setAuthError("Não conseguimos conectar ao MatchAnimal. Confira sua conexão e tente novamente."); }
    }
    void verifySession();
    return () => { active = false; };
  }, [attempt]);

  useEffect(() => {
    function refreshProfile(event: Event) {
      const detail = (event as CustomEvent<{ displayName?: string; city?: string; state?: string }>).detail;
      if (!detail) return;
      setAccountInfo((current) => ({ displayName: detail.displayName?.trim() || current.displayName, city: detail.city?.trim() ?? current.city, state: detail.state?.trim() ?? current.state }));
    }
    window.addEventListener("matchanimal:profile-updated", refreshProfile);
    return () => window.removeEventListener("matchanimal:profile-updated", refreshProfile);
  }, []);

  useEffect(() => {
    if (!authReady) return;
    const api = process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:4000";
    void Promise.allSettled([
      fetch(`${api}/api/notifications/unread-count`, { credentials: "include" }).then((response) => response.ok ? response.json() as Promise<{ count: number }> : null),
      fetch(`${api}/api/pets/matches`, { credentials: "include" }).then((response) => response.ok ? response.json() as Promise<unknown[]> : null),
    ]).then(([notifications, matches]) => { if (notifications.status === "fulfilled" && notifications.value) setUnreadNotifications(notifications.value.count); if (matches.status === "fulfilled" && matches.value) setMatchCount(matches.value.length); });
  }, [authReady, pathname]);

  async function logout() {
    try { await fetch(`${process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:4000"}/api/auth/logout`, { method: "POST", credentials: "include" }); }
    finally { window.location.assign("/"); }
  }

  const profileInitial = accountInfo.displayName === "Seu perfil" ? <PawPrint size={18}/> : Array.from(accountInfo.displayName)[0]?.toLocaleUpperCase("pt-BR") ?? <PawPrint size={18}/>;
  const locationLabel = [accountInfo.city, accountInfo.state].filter(Boolean).join(", ") || "Sua região";
  if (!authReady) return <div className="ma-session-state" role={authError ? "alert" : "status"}><PawPrint size={30}/>{authError ? <><h1>Vamos tentar de novo?</h1><p>{authError}</p><Button onClick={() => setAttempt((value) => value + 1)}>Tentar novamente</Button><Link href="/entrar">Voltar para entrar</Link></> : <><span className="session-spinner"/> Preparando seu cantinho…</>}</div>;

  return <SessionContext.Provider value={{ accountInfo, matchCount, unreadCount: unreadNotifications }}><div className="product-shell social-shell" data-page-title={title}>
    <a className="ma-skip-link" href="#main-content">Pular para o conteúdo</a>
    <header className="social-header">
      <Link className="wordmark social-wordmark" href="/dashboard" aria-label="MatchAnimal, início"><span className="wordmark-icon"><PawPrint size={17}/></span><span>match<span>animal</span></span></Link>
      <nav className="social-nav" aria-label="Navegação principal">{primaryLinks.map(({ href, label, icon: Icon }) => <Link key={href} aria-current={routeMatches(href, pathname) ? "page" : undefined} className={routeMatches(href, pathname) ? "social-nav-active" : ""} href={href}><Icon size={16}/><span>{label}</span>{label === "Conexões" && matchCount > 0 && <i>{matchCount}</i>}</Link>)}</nav>
      <div className="social-header-actions"><Link className="social-location" href="/configuracoes"><MapPin size={14}/>{locationLabel}</Link><button className="social-icon-button" onClick={() => setSearchOpen(true)} aria-label="Buscar na comunidade"><Search size={19}/></button><Link className="social-icon-button" href="/mensagens" aria-label="Mensagens"><MessageCircle size={19}/></Link><Link className="social-icon-button" href="/notificacoes" aria-label={`Notificações${unreadNotifications ? `, ${unreadNotifications} não lidas` : ""}`}><Bell size={19}/>{unreadNotifications > 0 && <i/>}</Link>{isModerator && <Link className="social-admin-link" href="/administracao" aria-label="Painel administrativo"><ShieldAlert size={19}/></Link>}<Link className="social-user-link" href="/configuracoes" aria-label="Abrir meu perfil"><span className="user-monogram">{profileInitial}</span><span className="social-user-name">{accountInfo.displayName}</span></Link><button className="social-logout" aria-label="Sair da conta" onClick={() => void logout()}><LogOut size={18}/></button></div>
    </header>
    <main className="product-main" id="main-content" tabIndex={-1}><div className="product-content">{children}</div></main>
    <nav className="product-bottom-nav" aria-label="Navegação móvel">{primaryLinks.map(({ href, label, icon: Icon }) => <Link key={href} aria-current={routeMatches(href, pathname) ? "page" : undefined} className={routeMatches(href, pathname) ? "product-bottom-active" : ""} href={href}><span className="product-nav-icon"><Icon size={19}/>{label === "Conexões" && <PawPrint className="product-nav-paw" size={9}/>}</span><small>{label}</small>{label === "Conexões" && matchCount > 0 && <i>{matchCount}</i>}</Link>)}</nav>
    <Dialog open={searchOpen} onClose={() => setSearchOpen(false)} title="O que vamos descobrir?" description="Encontre pets e histórias na comunidade."><form className="ma-search-form" role="search" action="/comunidade"><label htmlFor="community-search">Buscar na comunidade</label><input id="community-search" name="q" type="search" placeholder="Nome do pet, raça ou assunto" required maxLength={100}/><Button type="submit"><Search size={17}/>Buscar</Button></form></Dialog>
  </div></SessionContext.Provider>;
}

