"use client";

import dynamic from "next/dynamic";
import { useCallback, useEffect, useState, type FormEvent } from "react";
import { CalendarDays, Check, LoaderCircle, MapPin, Plus, Users } from "lucide-react";
const EventMap = dynamic(() => import("./event-map"), { ssr: false, loading: () => <div className="community-map-loading">Carregando mapa…</div> });
const api = process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:4000";
type Group = { id: string; name: string; slug: string; description: string; visibility: string; _count: { members: number; posts: number }; members: { approved: boolean }[] };
type EventItem = { id: string; title: string; description: string; startsAt: string; endsAt: string | null; locationLabel: string; latitude: number | null; longitude: number | null; capacity: number | null; visibility: string; isOrganizer: boolean; _count: { participants: number }; participants: { status: string }[] };

export function CommunityDirectory({ kind }: { kind: "groups" | "events" }) {
  const [actionBusy, setActionBusy] = useState("");
  const [groups, setGroups] = useState<Group[]>([]); const [events, setEvents] = useState<EventItem[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState(""); const [busy, setBusy] = useState(false); const [showForm, setShowForm] = useState(false); const [editingEvent, setEditingEvent] = useState<EventItem | null>(null);
  const load = useCallback(async () => { setLoading(true); setError(""); try { const response = await fetch(`${api}/api/community/${kind}`, { credentials: "include" }); if (!response.ok) throw new Error("Não foi possível carregar este espaço."); const data = await response.json(); kind === "groups" ? setGroups(data) : setEvents(data); } catch (reason) { setError((reason as Error).message); } finally { setLoading(false); } }, [kind]);
  useEffect(() => { void load(); }, [load]);

  async function create(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); setBusy(true); setError(""); const form = new FormData(event.currentTarget);
    const payload = kind === "groups" ? { name: form.get("name"), description: form.get("description"), visibility: form.get("visibility") } : { title: form.get("title"), description: form.get("description"), startsAt: new Date(String(form.get("startsAt"))).toISOString(), locationLabel: form.get("locationLabel"), latitude: form.get("latitude") ? Number(form.get("latitude")) : undefined, longitude: form.get("longitude") ? Number(form.get("longitude")) : undefined, capacity: form.get("capacity") ? Number(form.get("capacity")) : undefined, visibility: form.get("visibility") };
    try { const path = editingEvent ? `${api}/api/community/events/${editingEvent.id}` : `${api}/api/community/${kind}`; const response = await fetch(path, { method: editingEvent ? "PATCH" : "POST", credentials: "include", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) }); const result = await response.json(); if (!response.ok) throw new Error(result.message ?? "Não foi possível salvar."); setShowForm(false); setEditingEvent(null); await load(); } catch (reason) { setError((reason as Error).message); } finally { setBusy(false); }
  }
  async function joinGroup(id: string) { if (actionBusy) return; setActionBusy(id); setError(""); try { const response = await fetch(`${api}/api/community/groups/${id}/join`, { method: "POST", credentials: "include" }); if (!response.ok) throw new Error("Não foi possível solicitar entrada."); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Não foi possível solicitar entrada."); } finally { setActionBusy(""); } }
  async function attendEvent(id: string) { if (actionBusy) return; setActionBusy(id); setError(""); try { const response = await fetch(`${api}/api/community/events/${id}/attend`, { method: "POST", credentials: "include" }); const result = await response.json(); if (!response.ok) throw new Error(result.message ?? "Não foi possível confirmar presença."); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Não foi possível confirmar presença."); } finally { setActionBusy(""); } }
  async function cancelEvent(id: string) { if (actionBusy || !window.confirm("Cancelar este evento? Ele deixará de aparecer para participantes.")) return; setActionBusy(id); setError(""); try { const response = await fetch(`${api}/api/community/events/${id}`, { method: "DELETE", credentials: "include" }); if (!response.ok) { const result = await response.json(); throw new Error(result.message ?? "Não foi possível cancelar o evento."); } await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Não foi possível cancelar o evento."); } finally { setActionBusy(""); } }
  function editEvent(event: EventItem) { setEditingEvent(event); setShowForm(true); }

  const groupMode = kind === "groups";
  return <section className="community-directory"><header className="community-directory-heading"><div><span className="community-kicker">MATCHANIMAL SOCIAL</span><h1>{groupMode ? <>Grupos <em>e comunidades.</em></> : <>Eventos <em>pet.</em></>}</h1><p>{groupMode ? "Encontre sua turma e compartilhe experiências." : "Encontros seguros e atividades para os pets."}</p></div><button onClick={() => { setEditingEvent(null); setShowForm((value) => !value); }}><Plus size={15}/>{groupMode ? "Criar grupo" : "Criar evento"}</button></header>
    {showForm && <form className="community-directory-form" onSubmit={(event) => void create(event)}>{groupMode ? <><label>Nome do grupo<input name="name" minLength={2} maxLength={100} required placeholder="Ex.: Passeios com cães em Salvador"/></label><label>Descrição<textarea name="description" minLength={5} maxLength={1000} required/></label></> : <><label>Nome do evento<input name="title" defaultValue={editingEvent?.title} maxLength={120} required/></label><label>Descrição<textarea name="description" defaultValue={editingEvent?.description} maxLength={2000} required/></label><div className="community-form-row"><label>Data e hora<input name="startsAt" type="datetime-local" defaultValue={editingEvent ? toLocalInput(editingEvent.startsAt) : undefined} required min={editingEvent ? undefined : toLocalInput(new Date(Date.now() + 3600000).toISOString())}/></label><label>Limite de pessoas<input name="capacity" type="number" min="1" max="10000" defaultValue={editingEvent?.capacity ?? undefined}/></label></div><label>Local do evento<input name="locationLabel" defaultValue={editingEvent?.locationLabel} maxLength={180} required placeholder="Parque, praça ou espaço pet"/></label><div className="community-form-row"><label>Latitude (opcional)<input name="latitude" type="number" step="any" min="-90" max="90" defaultValue={editingEvent?.latitude ?? undefined}/></label><label>Longitude (opcional)<input name="longitude" type="number" step="any" min="-180" max="180" defaultValue={editingEvent?.longitude ?? undefined}/></label></div></>}<label>Visibilidade<select name="visibility" defaultValue={editingEvent?.visibility ?? "PUBLIC"}><option value="PUBLIC">Público</option><option value="PRIVATE">Privado</option></select></label><button type="submit" disabled={busy}>{busy ? <LoaderCircle size={14}/> : editingEvent ? <Check size={14}/> : <Plus size={14}/>} {editingEvent?"Salvar alterações":groupMode?"Criar grupo":"Criar evento"}</button></form>}
    {error && <p className="community-alert" role="alert">{error}</p>}
    {loading ? <div className="community-state"><LoaderCircle className="community-spin"/> Carregando…</div> : groupMode ? groups.length ? <div className="community-directory-grid">{groups.map((group) => <article className="community-directory-card" key={group.id}><span className="directory-card-icon"><Users size={20}/></span><small>{group.visibility === "PRIVATE" ? "GRUPO PRIVADO" : "COMUNIDADE ABERTA"}</small><h2>{group.name}</h2><p>{group.description}</p><footer><span>{group._count.members} membros · {group._count.posts} publicações</span>{group.members[0]?.approved ? <a href={`/grupos/detalhe?id=${encodeURIComponent(group.id)}`}>Abrir grupo</a> : <button disabled={!!actionBusy || !!group.members.length} onClick={() => void joinGroup(group.id)}>{actionBusy === group.id ? "Enviando…" : group.members.length ? "Solicitação enviada" : group.visibility === "PRIVATE" ? "Solicitar entrada" : "Participar"}</button>}</footer></article>)}</div> : <DirectoryEmpty label="Ainda não há grupos por aqui."/> : events.length ? <div className="community-events-list">{events.map((event) => <article className="community-event-card" key={event.id}><div className="community-event-copy"><span className="community-event-date"><CalendarDays size={14}/>{new Intl.DateTimeFormat("pt-BR", { dateStyle: "medium", timeStyle: "short" }).format(new Date(event.startsAt))}</span><h2>{event.title}</h2><p>{event.description}</p><span className="community-event-location"><MapPin size={13}/>{event.locationLabel}</span><footer><small>{event._count.participants}{event.capacity ? ` / ${event.capacity}` : ""} participantes</small>{event.isOrganizer ? <span className="event-organizer-actions"><button disabled={!!actionBusy} onClick={()=>editEvent(event)}>Editar</button><button disabled={!!actionBusy} onClick={()=>void cancelEvent(event.id)}>Cancelar evento</button></span> : event.participants.length ? <b>Presença confirmada</b> : <button disabled={!!actionBusy} onClick={() => void attendEvent(event.id)}>Vou participar</button>}</footer></div>{event.latitude !== null && event.longitude !== null && <EventMap latitude={event.latitude} longitude={event.longitude} title={event.title}/>}</article>)}</div> : <DirectoryEmpty label="Ainda não há eventos próximos."/>}
  </section>;
}

export function GroupTimeline({ groupId }: { groupId: string }) {
  const [loading, setLoading] = useState(true);
  const [posts, setPosts] = useState<{ id: string; body: string; createdAt: string; author: { tutor: { displayName: string } | null } }[]>([]); const [body, setBody] = useState(""); const [error, setError] = useState(""); const [busy, setBusy] = useState(false);
  const load = useCallback(async () => { setLoading(true); setError(""); try { const response = await fetch(`${api}/api/community/groups/${groupId}/posts`, { credentials: "include" }); if (!response.ok) throw new Error("Você precisa participar deste grupo para ver as publicações."); setPosts(await response.json()); } catch (cause) { setError(cause instanceof Error ? cause.message : "Não foi possível carregar as publicações."); } finally { setLoading(false); } }, [groupId]);
  useEffect(() => { void load(); }, [load]);
  async function publish(event: FormEvent) { event.preventDefault(); if (!body.trim()) return; setBusy(true); try { const response = await fetch(`${api}/api/community/groups/${groupId}/posts`, { method: "POST", credentials: "include", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ body }) }); const result = await response.json(); if (!response.ok) throw new Error(result.message ?? "Não foi possível publicar."); setBody(""); await load(); } catch (reason) { setError((reason as Error).message); } finally { setBusy(false); } }
  return <section className="community-directory"><a className="community-back-link" href="/grupos">← Todas as comunidades</a><header className="community-directory-heading"><div><span className="community-kicker">GRUPO MATCHANIMAL</span><h1>Conversas <em>da comunidade.</em></h1></div></header>{error && <p className="community-alert">{error}</p>}<form className="community-group-composer" onSubmit={publish}><textarea aria-label="Publicação no grupo" value={body} onChange={(event) => setBody(event.target.value)} maxLength={2000} placeholder="Compartilhe uma dica ou história com o grupo"/><button disabled={busy || !body.trim()}>{busy ? "Publicando…" : "Publicar no grupo"}</button></form><div className="community-group-posts">{posts.map((post) => <article key={post.id}><small>{post.author.tutor?.displayName ?? "Tutor"} · {new Intl.DateTimeFormat("pt-BR", { dateStyle: "medium" }).format(new Date(post.createdAt))}</small><p>{post.body}</p></article>)}</div>{loading && <div className="community-state" role="status"><LoaderCircle className="community-spin"/> Carregando publicações…</div>}{!loading && !posts.length && !error && <DirectoryEmpty label="O grupo ainda não tem publicações."/>}</section>;
}

function DirectoryEmpty({ label }: { label: string }) { return <div className="community-empty"><span><CalendarDays size={22}/></span><h2>{label}</h2><p>Você pode começar criando o primeiro espaço para a comunidade.</p></div>; }
function toLocalInput(value: string) { const date = new Date(value); return new Date(date.getTime() - date.getTimezoneOffset() * 60_000).toISOString().slice(0,16); }

