"use client";

import { useCallback, useEffect, useRef, useState, type FormEvent, type ChangeEvent } from "react";
import Link from "next/link";
import { useDialogAccessibility } from "@/lib/use-dialog-accessibility";
import { io, type Socket } from "socket.io-client";
import { Bookmark, CalendarDays, Compass, Heart, ImagePlus, LoaderCircle, MapPin, MessageCircle, MoreHorizontal, PawPrint, Pause, Play, Plus, Search, Send, Share2, ShieldAlert, Users, X } from "lucide-react";
import { PetFriends } from "@/components/pet-friends";
import { petFeedback } from "@/lib/native-feedback";

const api = process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:4000";
type FeedMedia = { id: string; storageKey: string; mediaType: string; mimeType: string; sizeBytes: number };
export type FeedPost = { id: string; body: string; kind: string; visibility: string; locationLabel: string | null; createdAt: string; authorId: string; author: { id: string; tutor: { displayName: string; profilePhotoUrl: string | null } | null }; pet: { id: string; name: string; species: string; breed: string | null; coverPhotoUrl: string | null; followedByMe: boolean; followerCount: number } | null; media: FeedMedia[]; _count: { likes: number; comments: number }; likedByMe: boolean; savedByMe: boolean };
type Story = { id: string; mediaKey: string; mediaType: string; caption: string | null; expiresAt: string; pet: { name: string; coverPhotoUrl: string | null } | null; author: { tutor: { displayName: string; profilePhotoUrl: string | null } | null }; viewedByMe: boolean };
type MyPet = { id: string; name: string };
const mediaUrl = (key: string) => `${api}/api/community/media/${key}`;
const acceptedMedia = ["image/jpeg", "image/png", "image/webp", "video/mp4", "video/webm"];
function mediaError(files: File[]) {
  if (files.some((file) => !acceptedMedia.includes(file.type))) return "Use fotos JPG, PNG ou WebP e vídeos MP4 ou WebM.";
  if (files.some((file) => file.size > (file.type.startsWith("video/") ? 25 : 8) * 1024 * 1024)) return "Cada foto pode ter até 8 MB e cada vídeo até 25 MB.";
  return "";
}

export function CommunityFeed() {
  const [posts, setPosts] = useState<FeedPost[]>([]); const [cursor, setCursor] = useState<string | null>(null); const [mode, setMode] = useState("for-you");
  const [loading, setLoading] = useState(true); const [loadingMore, setLoadingMore] = useState(false); const [error, setError] = useState("");
  const [body, setBody] = useState(""); const [files, setFiles] = useState<File[]>([]); const [posting, setPosting] = useState(false); const [stories, setStories] = useState<Story[]>([]); const [activeStory, setActiveStory] = useState<Story | null>(null); const [myPets, setMyPets] = useState<MyPet[]>([]); const [petId, setPetId] = useState(""); const [visibility, setVisibility] = useState("PUBLIC"); const [searchText, setSearchText] = useState(""); const [search, setSearch] = useState("");
  const [previews, setPreviews] = useState<string[]>([]);
  const [ready, setReady] = useState(false);
  const [momentBusy, setMomentBusy] = useState(false);
  const [notice, setNotice] = useState("");
  const composerRef = useRef<HTMLTextAreaElement>(null);
  useEffect(() => {
    const query = new URLSearchParams(window.location.search);
    const term = query.get("q")?.trim() ?? "";
    setSearch(term); setSearchText(term); setReady(true);
    if (query.get("compose") === "1") requestAnimationFrame(() => { composerRef.current?.scrollIntoView({ block: "center", behavior: window.matchMedia("(prefers-reduced-motion: reduce)").matches ? "instant" : "smooth" }); composerRef.current?.focus({ preventScroll: true }); });
  }, []);
  const openStory = useCallback((story: Story) => { setActiveStory(story); void fetch(`${api}/api/community/stories/${story.id}/view`, { method: "POST", credentials: "include" }); }, []);
  const stepStory = useCallback((direction: -1 | 1) => { if (!activeStory) return; const nextIndex = stories.findIndex((item) => item.id === activeStory.id) + direction; if (nextIndex < 0 || nextIndex >= stories.length) { setActiveStory(null); return; } openStory(stories[nextIndex]); }, [activeStory, openStory, stories]);

  const load = useCallback(async (reset = true, pageCursor?: string | null) => {
    if (reset) setLoading(true); else setLoadingMore(true);
    setError("");
    try {
      const query = new URLSearchParams({ mode, limit: "18" }); if (search) query.set("q", search); if (!reset && pageCursor) query.set("cursor", pageCursor);
      const response = await fetch(`${api}/api/community/feed?${query}`, { credentials: "include" });
      if (!response.ok) throw new Error("Não foi possível carregar a comunidade.");
      const result = await response.json() as { items: FeedPost[]; nextCursor: string | null };
      setPosts((current) => reset ? result.items : [...current, ...result.items.filter((post) => !current.some((item) => item.id === post.id))]); setCursor(result.nextCursor);
    } catch (reason) { setError((reason as Error).message); } finally { setLoading(false); setLoadingMore(false); }
  }, [mode, search]);

  useEffect(() => { if (!ready) return; setCursor(null); void load(true); }, [ready, load]);
  useEffect(() => { let alive = true; void fetch(`${api}/api/community/stories`, { credentials: "include" }).then((response) => response.ok ? response.json() as Promise<Story[]> : []).then((result) => { if (alive) setStories(result); }).catch(() => undefined); return () => { alive = false; }; }, []);
  useEffect(() => { let alive = true; void fetch(`${api}/api/pets/mine`, { credentials: "include" }).then((response) => response.ok ? response.json() as Promise<MyPet[]> : []).then((result) => { if (alive) setMyPets(result); }).catch(() => undefined); return () => { alive = false; }; }, []);
  useEffect(() => { const urls = files.map((file) => URL.createObjectURL(file)); setPreviews(urls); return () => urls.forEach((url) => URL.revokeObjectURL(url)); }, [files]);
  useEffect(() => {
    const socket: Socket = io(`${api}/realtime`, { withCredentials: true, transports: ["websocket"], reconnectionAttempts: 10 });
    const refresh = () => { void load(true); };
    socket.on("feed:post:created", refresh); socket.on("feed:post:updated", refresh); socket.on("feed:post:deleted", refresh);
    return () => { socket.disconnect(); };
  }, [load]);

  async function publish(event: FormEvent) {
    event.preventDefault(); if (!body.trim() && !files.length || posting) return;
    setPosting(true); setError("");
    try {
      let mediaKeys: string[] = [];
      if (files.length) {
        const form = new FormData(); files.forEach((file) => form.append("files", file));
        const upload = await fetch(`${api}/api/community/media`, { method: "POST", credentials: "include", body: form });
        const uploaded = await upload.json() as { key?: string; message?: string }[] | { message?: string };
        if (!upload.ok || !Array.isArray(uploaded)) throw new Error((uploaded as { message?: string }).message ?? "Não foi possível enviar os arquivos.");
        mediaKeys = uploaded.map((file) => file.key!).filter(Boolean);
      }
      const response = await fetch(`${api}/api/community/posts`, { method: "POST", credentials: "include", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ body, mediaKeys, petId: petId || undefined, visibility }) });
      const result = await response.json() as { message?: string };
      if (!response.ok) throw new Error(result.message ?? "Não foi possível publicar.");
      setBody(""); setFiles([]); setNotice("Seu momento foi publicado na comunidade."); await load(true);
    } catch (reason) { setError((reason as Error).message); } finally { setPosting(false); }
  }

  async function toggleLike(postId: string) {
    const before = posts; setPosts((all) => all.map((post) => post.id === postId ? { ...post, likedByMe: !post.likedByMe, _count: { ...post._count, likes: post._count.likes + (post.likedByMe ? -1 : 1) } } : post));
    try { const response = await fetch(`${api}/api/community/posts/${postId}/like`, { method: "POST", credentials: "include" }); if (!response.ok) throw new Error(); const result = await response.json() as { liked: boolean; count: number }; setPosts((all) => all.map((post) => post.id === postId ? { ...post, likedByMe: result.liked, _count: { ...post._count, likes: result.count } } : post)); }
    catch { setPosts(before); setError("Não foi possível atualizar a curtida."); }
  }

  async function toggleSave(postId: string) {
    try { const response = await fetch(`${api}/api/community/posts/${postId}/save`, { method: "POST", credentials: "include" }); if (!response.ok) throw new Error(); const result = await response.json() as { saved: boolean }; setPosts((all) => all.map((post) => post.id === postId ? { ...post, savedByMe: result.saved } : post)); }
    catch { setError("Não foi possível salvar a publicação."); }
  }

  async function selectFiles(event: ChangeEvent<HTMLInputElement>) { const chosen = [...(event.target.files ?? [])]; event.target.value = ""; const invalid = mediaError(chosen); if (invalid) { setError(invalid); return; } if (chosen.length + files.length > 6) { setError("Escolha até seis arquivos por publicação."); return; } setError(""); setFiles((current) => [...current, ...chosen]); }
  async function createMoment(event: ChangeEvent<HTMLInputElement>) { const file = event.target.files?.[0]; event.target.value = ""; if (!file || momentBusy) return; const invalid = mediaError([file]); if (invalid) { setError(invalid); return; } setMomentBusy(true); setError(""); try { const form = new FormData(); form.append("files", file); const uploaded = await fetch(`${api}/api/community/media`, { method: "POST", credentials: "include", body: form }); const media = await uploaded.json() as { key?: string }[]; if (!uploaded.ok || !media[0]?.key) throw new Error("Não foi possível enviar a mídia."); const created = await fetch(`${api}/api/community/stories`, { method: "POST", credentials: "include", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ petId: petId || undefined, mediaKey: media[0].key, mediaType: file.type.startsWith("video/") ? "VIDEO" : "IMAGE", visibility: "FOLLOWERS" }) }); if (!created.ok) throw new Error("Não foi possível publicar o momento."); const refreshed = await fetch(`${api}/api/community/stories`, { credentials: "include" }); if (refreshed.ok) setStories(await refreshed.json()); setNotice("Momento publicado. Ele ficará disponível por 24 horas."); } catch (reason) { setError((reason as Error).message); } finally { setMomentBusy(false); } }
  async function report(postId: string) { const reason = window.prompt("Conte por que você está denunciando esta publicação."); if (!reason?.trim()) return; try { const response = await fetch(`${api}/api/safety/reports`, { method: "POST", credentials: "include", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ targetType: "POST", targetId: postId, reason: reason.trim() }) }); if (!response.ok) throw new Error(); setNotice("Denúncia enviada para análise."); } catch { setError("Não foi possível enviar a denúncia. Tente novamente."); } }

  return <div className="community-layout">
    <aside className="community-rail community-left"><div className="community-rail-card"><span className="community-rail-eyebrow">SEU ESPAÇO SOCIAL</span><a className="community-rail-link community-rail-active" href="/comunidade"><Users size={16}/> Feed da comunidade</a><a className="community-rail-link" href="/comunidade/explorar"><Compass size={16}/> Explorar</a><a className="community-rail-link" href="/grupos"><PawPrint size={16}/> Grupos</a><a className="community-rail-link" href="/eventos"><CalendarDays size={16}/> Eventos pet</a></div><div className="community-care-note"><ShieldAlert size={17}/><strong>Comunidade segura</strong><p>Respeito e bem-estar dos animais vêm primeiro.</p><a href="/seguranca">Conheça nossas diretrizes</a></div></aside>
    <div className="community-main">
      <nav className="community-local-nav" aria-label="Espaços da comunidade"><Link href="/comunidade"><Users size={16}/> Feed</Link><Link href="/comunidade/explorar"><Compass size={16}/> Explorar</Link><Link href="/grupos"><PawPrint size={16}/> Grupos</Link><Link href="/eventos"><CalendarDays size={16}/> Eventos</Link></nav>
      <header className="community-heading"><div><span className="community-kicker">MATCHANIMAL SOCIAL</span><h1>Comunidade <em>pet.</em></h1><p>Momentos reais, histórias e novas amizades.</p></div><button className="community-compose-cta" onClick={() => composerRef.current?.focus()}><Plus size={16}/> Publicar</button></header>
      <form className="community-search" onSubmit={(event) => { event.preventDefault(); setSearch(searchText.trim()); }}><Search size={16}/><input value={searchText} onChange={(event) => setSearchText(event.target.value)} placeholder="Buscar pets, tutores, raças ou hashtags" aria-label="Buscar na comunidade"/><button type="submit">Buscar</button></form>
      <section className="community-stories" aria-label="Momentos"><div className="community-section-top"><strong>Momentos</strong><span>Stories somem em 24 horas</span></div><div className="community-story-list"><label className="community-story community-story-new" tabIndex={momentBusy ? -1 : 0} role="button" aria-label={momentBusy ? "Publicando momento" : "Adicionar momento"} onKeyDown={(event) => { if (event.key === "Enter" || event.key === " ") { event.preventDefault(); event.currentTarget.querySelector("input")?.click(); } }}><span><Plus size={19}/></span><small>{momentBusy ? "Publicando…" : "Seu momento"}<input disabled={momentBusy} type="file" accept="image/jpeg,image/png,image/webp,video/mp4,video/webm" onChange={(event) => void createMoment(event)} hidden/></small></label>{stories.map((story) => <button className={`community-story ${story.viewedByMe ? "community-story-seen" : ""}`} key={story.id} onClick={() => openStory(story)}><span style={story.pet?.coverPhotoUrl ? { backgroundImage: `url(${story.pet.coverPhotoUrl})` } : story.author.tutor?.profilePhotoUrl ? { backgroundImage: `url(${story.author.tutor.profilePhotoUrl})` } : undefined}><PawPrint size={18}/></span><small>{story.pet?.name ?? story.author.tutor?.displayName ?? "Pet"}</small></button>)}</div></section>
      <form className="community-composer" id="community-composer" onSubmit={publish}><div className="composer-avatar"><PawPrint size={18}/></div><div className="composer-content"><textarea ref={composerRef} value={body} onChange={(event) => setBody(event.target.value)} maxLength={2000} placeholder="O que seu pet aprontou hoje?" aria-label="Texto da publicação"/><div className="composer-preview">{files.map((file, index) => <span key={`${file.name}-${index}`}>{file.type.startsWith("video/") ? <video src={previews[index]} muted/> : <img src={previews[index]} alt={`Prévia ${file.name}`}/>}<button type="button" onClick={() => setFiles((all) => all.filter((_, i) => i !== index))} aria-label={`Remover ${file.name}`}><X size={12}/></button></span>)}</div><div className="composer-footer"><div className="composer-options"><label className="composer-tool" tabIndex={0} role="button" onKeyDown={(event) => { if (event.key === "Enter" || event.key === " ") { event.preventDefault(); event.currentTarget.querySelector("input")?.click(); } }}><ImagePlus size={15}/> Foto ou vídeo<input type="file" accept="image/jpeg,image/png,image/webp,video/mp4,video/webm" multiple onChange={(event) => void selectFiles(event)} hidden/></label><select aria-label="Publicar em nome do animal" value={petId} onChange={(event) => { setPetId(event.target.value); if (!event.target.value && visibility === "FOLLOWERS") setVisibility("PUBLIC"); }}><option value="">Meu perfil</option>{myPets.map((pet) => <option key={pet.id} value={pet.id}>{pet.name}</option>)}</select><select aria-label="Privacidade da publicação" value={visibility} onChange={(event) => setVisibility(event.target.value)}><option value="PUBLIC">Pública</option><option value="FOLLOWERS" disabled={!petId}>Seguidores</option><option value="PRIVATE">Só eu</option></select></div><button type="submit" disabled={posting || (!body.trim() && !files.length)}>{posting ? <LoaderCircle className="community-spin" size={15}/> : <Send size={14}/>} Publicar</button></div></div></form>
      <nav className="community-feed-tabs" aria-label="Ordenar publicações">{[{ id: "for-you", label: "Para você" }, { id: "following", label: "Seguindo" }, { id: "nearby", label: "Próximos" }].map((tab) => <button key={tab.id} aria-pressed={mode === tab.id} className={mode === tab.id ? "community-tab-active" : ""} onClick={() => setMode(tab.id)}>{tab.label}</button>)}</nav>
      {notice && <p className="ma-action-note" role="status">{notice}</p>}
      {error && <div className="community-alert" role="status">{error}<button onClick={() => setError("")} aria-label="Fechar aviso"><X size={14}/></button></div>}
      {loading ? <div className="community-state"><LoaderCircle className="community-spin"/> Carregando publicações…</div> : posts.length ? <div className="community-post-list">{posts.map((post) => <PostCard key={post.id} post={post} onLike={() => { void petFeedback("tap"); void toggleLike(post.id); }} onSave={() => void toggleSave(post.id)} onReport={() => void report(post.id)} onChanged={() => void load(true)}/>)}</div> : <div className="community-empty pet-empty-state"><PetFriends mood="welcome"/><h2>Seu feed começa com uma história.</h2><p>Publique o primeiro momento ou siga um perfil para acompanhar novidades.</p></div>}
      {cursor && !loading && <button className="community-load-more" disabled={loadingMore} onClick={() => void load(false, cursor)}>{loadingMore ? "Carregando…" : "Carregar mais publicações"}</button>}
    </div>
    <aside className="community-rail community-right"><div className="community-rail-card"><span className="community-rail-eyebrow">SEU MATCHANIMAL</span><a className="community-mini-link" href="/explorar"><Heart size={15}/> Descubra matches</a><a className="community-mini-link" href="/animais"><PawPrint size={15}/> Seus animais</a></div><div className="community-rail-card community-trends"><span className="community-rail-eyebrow">UM BOM COMEÇO</span><h3>Mais comunidade,<br/>mais cuidado.</h3><p>Compartilhe dicas, encontros seguros e histórias que ajudam outros tutores.</p><a href="/grupos">Encontrar uma comunidade <Users size={13}/></a></div><div className="community-footer-note">MatchAnimal · conectando com cuidado</div></aside>
    {activeStory && <StoryViewer story={activeStory} onClose={() => setActiveStory(null)} onNext={()=>stepStory(1)} onPrevious={()=>stepStory(-1)} />}
  </div>;
}

export function PostCard({ post, onLike, onSave, onReport, onChanged }: { post: FeedPost; onLike: () => void; onSave: () => void; onReport: () => void; onChanged: () => void }) {
  const [showComments, setShowComments] = useState(false); const [comments, setComments] = useState<{ id: string; body: string; createdAt: string; author: { tutor: { displayName: string } | null } }[]>([]); const [draft, setDraft] = useState(""); const [busy, setBusy] = useState(false);
  const [feedback, setFeedback] = useState(""); const [commentsLoading, setCommentsLoading] = useState(false); const [requested, setRequested] = useState(false);
  const [followed, setFollowed] = useState(post.pet?.followedByMe ?? false); const [followerCount, setFollowerCount] = useState(post.pet?.followerCount ?? 0); const [followBusy, setFollowBusy] = useState(false);
  async function toggleFollow() { if (!post.pet || followBusy) return; setFollowBusy(true); try { const response = await fetch(`${api}/api/community/pets/${post.pet.id}/follow`, { method: "POST", credentials: "include" }); if (!response.ok) throw new Error(); const result = await response.json() as { followed: boolean; requested: boolean; count: number }; setFollowed(result.followed); setRequested(result.requested); setFollowerCount(result.count); setFeedback(result.requested ? "Solicitação de acompanhamento enviada." : ""); } catch { setFeedback("Não foi possível atualizar o acompanhamento. Tente novamente."); } finally { setFollowBusy(false); } }
  async function loadComments() { setCommentsLoading(true); try { const response = await fetch(`${api}/api/community/posts/${post.id}/comments`, { credentials: "include" }); if (!response.ok) throw new Error(); setComments(await response.json()); } catch { setFeedback("Não foi possível carregar os comentários. Feche e abra os comentários para tentar novamente."); } finally { setCommentsLoading(false); } }
  async function addComment(event: FormEvent) { event.preventDefault(); if (!draft.trim() || busy) return; setBusy(true); try { const response = await fetch(`${api}/api/community/posts/${post.id}/comments`, { method: "POST", credentials: "include", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ body: draft }) }); if (!response.ok) throw new Error(); setDraft(""); await loadComments(); onChanged(); } catch { setFeedback("Seu comentário não foi enviado. O texto foi mantido para você tentar novamente."); } finally { setBusy(false); } }
  async function sharePost() {
    const url = `${window.location.origin}/comunidade/publicacao?postId=${encodeURIComponent(post.id)}`;
    try {
      if (navigator.share) await navigator.share({ title: `Um momento de ${post.pet?.name ?? "MatchAnimal"}`, url });
