"use client";

import { useEffect, useMemo, useRef, useState, type FormEvent, type PointerEvent } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { ArrowRight, Ban, Check, ChevronDown, Filter, Heart, Info, MapPin, PawPrint, ShieldCheck, Sparkles, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Dialog } from "@/components/ui/dialog";
import { useDialogAccessibility } from "@/lib/use-dialog-accessibility";
import { PetFriends } from "@/components/pet-friends";
import { petFeedback } from "@/lib/native-feedback";

type Intent = "FRIENDSHIP" | "RESPONSIBLE_BREEDING" | "ADOPTION";
type Profile = { id: string; name: string; age: string; species: string; breed: string; sex: string; size: string; city: string; distance: string; intent: Intent; score: number | null; traits: string[]; photo: string; photoUrl?: string | null; note: string; health: boolean; mutual?: boolean; demo?: boolean };
type ApiPet = { id: string; name: string; species: "DOG" | "CAT" | "OTHER"; speciesOther?: string | null; breed?: string | null; sex?: "FEMALE" | "MALE" | "UNKNOWN"; size?: string; birthDate?: string | null; bio?: string | null; intent: Intent; temperament?: string[]; city?: string | null; state?: string | null; coverPhotoUrl?: string | null; approximateDistanceKm?: number | null; compatibility?: { score?: number | null } | null };
type OwnPet = { id: string; name: string; species: string; intent: Intent; coverPhotoUrl?: string | null };

function mapApiPet(pet: ApiPet): Profile {
  return {
    id: pet.id, name: pet.name, age: ageLabel(pet.birthDate), species: speciesLabels[pet.species] ?? pet.speciesOther ?? "Outro", breed: pet.breed ?? "Sem raça informada",
    sex: pet.sex === "FEMALE" ? "Fêmea" : pet.sex === "MALE" ? "Macho" : "Sexo não informado", size: sizes[pet.size ?? "UNKNOWN"] ?? "Não informado",
    city: [pet.city, pet.state].filter(Boolean).join(", ") || "Região não informada", distance: pet.approximateDistanceKm ? `~${pet.approximateDistanceKm} km` : "Região aprox.", intent: pet.intent,
    score: pet.compatibility?.score ?? null, traits: pet.temperament ?? [], photo: "photo-1543466835-00a7907e9de1", photoUrl: pet.coverPhotoUrl,
    note: pet.bio || "Este perfil ainda não tem uma apresentação. Converse com o tutor para saber mais.", health: false, demo: false,
  };
}

const demoProfiles: Profile[] = [
  { id:"p1", name:"Jujuba", age:"2 anos", species:"Cão", breed:"Golden Retriever", sex:"Fêmea", size:"Médio", city:"Pinheiros, São Paulo", distance:"2 km", intent:"FRIENDSHIP", score:94, traits:["Sociável","Adora passeios","Brincalhona"], photo:"photo-1552053831-71594a27632d", note:"Meu lugar favorito é o parque. Sou amiga de todo mundo e adoro um passeio sem pressa. 🐾", health:true, mutual:true, demo:true },
  { id:"p2", name:"Bento", age:"3 anos", species:"Cão", breed:"Sem raça definida", sex:"Macho", size:"Médio", city:"Vila Madalena, São Paulo", distance:"4 km", intent:"FRIENDSHIP", score:91, traits:["Carinhoso","Calmo","Sociável"], photo:"photo-1543466835-00a7907e9de1", note:"Companhia boa, focinho curioso e especialista em descobrir novos caminhos.", health:true, demo:true },
  { id:"p3", name:"Nina", age:"1 ano", species:"Gato", breed:"Siamês", sex:"Fêmea", size:"Pequeno", city:"Perdizes, São Paulo", distance:"5 km", intent:"FRIENDSHIP", score:88, traits:["Curiosa","Carinhosa","Caseira"], photo:"photo-1511044568932-338cba0ad803", note:"Busco uma amizade felina com introdução calma e respeitando meu tempo.", health:true, demo:true },
  { id:"p4", name:"Sol", age:"2 anos", species:"Cão", breed:"Border Collie", sex:"Fêmea", size:"Médio", city:"Sumaré, São Paulo", distance:"7 km", intent:"RESPONSIBLE_BREEDING", score:86, traits:["Ativa","Exames informados","Acompanhamento"], photo:"photo-1508898578281-774ac4893c0d", note:"A família procura conversar com tutores e profissionais antes de qualquer apresentação.", health:false, demo:true },
  { id:"p5", name:"Tico", age:"8 meses", species:"Cão", breed:"Caramelo", sex:"Macho", size:"Pequeno", city:"Vila Mariana, São Paulo", distance:"8 km", intent:"ADOPTION", score:0, traits:["Brincalhão","Em lar temporário","Dócil"], photo:"photo-1551717743-49959800b1f6", note:"Estou em um lar temporário e procuro uma família que tenha tempo para acompanhar minha adaptação.", health:true, demo:true },
  { id:"p6", name:"Frida", age:"4 anos", species:"Gato", breed:"SRD", sex:"Fêmea", size:"Pequeno", city:"Consolação, São Paulo", distance:"3 km", intent:"ADOPTION", score:0, traits:["Tranquila","Independente","Carinhosa"], photo:"photo-1573865526739-10659fec78a5", note:"Gosto de uma casa tranquila, janelas seguras e carinho no meu tempo.", health:true, demo:true },
];

const intentLabels: Record<Intent, string> = { FRIENDSHIP:"Amizade", RESPONSIBLE_BREEDING:"Relacionamento responsável", ADOPTION:"Disponível para adoção" };
const speciesLabels: Record<ApiPet["species"], string> = { DOG:"Cão", CAT:"Gato", OTHER:"Outro" };
const sizes: Record<string, string> = { SMALL:"Pequeno", MEDIUM:"Médio", LARGE:"Grande", EXTRA_LARGE:"Gigante", UNKNOWN:"Não informado" };
const api = process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:4000";
function ageLabel(birthDate?: string | null) { if (!birthDate) return "idade não informada"; const date = new Date(birthDate); let years = new Date().getFullYear() - date.getFullYear(); if (new Date().getMonth() < date.getMonth() || (new Date().getMonth() === date.getMonth() && new Date().getDate() < date.getDate())) years--; return years < 1 ? "menos de 1 ano" : `${years} ${years === 1 ? "ano" : "anos"}`; }

export function ExploreFeed() {
  const [intent, setIntent] = useState<"ALL" | Intent>("ALL");
  const [species, setSpecies] = useState("ALL");
  const [radiusKm, setRadiusKm] = useState(50);
  const [index, setIndex] = useState(0);
  const [profiles, setProfiles] = useState<Profile[]>([]);
  const [ownPets, setOwnPets] = useState<OwnPet[]>([]);
  const [viewerPetId, setViewerPetId] = useState("");
  const [matches, setMatches] = useState<Profile[]>([]);
  const [modal, setModal] = useState<Profile | null>(null);
  const [matchCelebration, setMatchCelebration] = useState<Profile | null>(null);
  const [applicationSent, setApplicationSent] = useState(false);
  const [applicationError, setApplicationError] = useState("");
  const [notice, setNotice] = useState("");
  const [usingDemo, setUsingDemo] = useState(false);
  const [actionBusy, setActionBusy] = useState(false);
  const [preferencesOpen, setPreferencesOpen] = useState(false);
  const [profilePreview, setProfilePreview] = useState<Profile | null>(null);
  const pointerStart = useRef<{ x: number; y: number; id: number } | null>(null);
  const cardRef = useRef<HTMLElement>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [attempt, setAttempt] = useState(0);
  const [compatibilityOpen, setCompatibilityOpen] = useState(false);
  const modalRef = useDialogAccessibility<HTMLElement>(!!modal, () => setModal(null));
  const previewRef = useDialogAccessibility<HTMLElement>(!!profilePreview, () => setProfilePreview(null));
  const celebrationRef = useDialogAccessibility<HTMLElement>(!!matchCelebration, () => setMatchCelebration(null));
  const router = useRouter();

  useEffect(() => {
    let active = true;
    setLoading(true); setError("");
    fetch(`${api}/api/pets/mine`, { credentials: "include" }).then(async (response) => {
      if (!response.ok) throw new Error();
      const pets = await response.json() as OwnPet[];
      if (!active) return;
      setOwnPets(pets);
      const requestedPet = new URLSearchParams(window.location.search).get("pet");
      const selectedPet = pets.find((pet) => pet.id === requestedPet) ?? pets[0];
      if (selectedPet) setViewerPetId(selectedPet.id);
      else { setProfiles(demoProfiles); setUsingDemo(true); setLoading(false); }
    }).catch(() => { if (active) { setError("Não foi possível carregar seus pets. Tente novamente."); setLoading(false); } });
    return () => { active = false; };
  }, [attempt]);

  useEffect(() => {
    if (!viewerPetId) return;
    let active = true;
    setLoading(true); setError("");
    fetch(`${api}/api/pets/explore?viewerPetId=${encodeURIComponent(viewerPetId)}&radiusKm=${radiusKm}`, { credentials: "include" }).then(async (response) => {
      if (!response.ok) throw new Error();
      const results = await response.json() as ApiPet[];
      if (!active) return;
      const mapped = results.map(mapApiPet);
      setProfiles(mapped);
      setUsingDemo(false);
      setIndex(0);
    }).catch(() => { if (active) setError("Não conseguimos carregar a descoberta. Confira sua conexão e tente novamente."); }).finally(() => { if (active) setLoading(false); });
    return () => { active = false; };
  }, [viewerPetId, radiusKm, attempt]);

  const filtered = useMemo(() => profiles.filter((pet) => (intent === "ALL" || pet.intent === intent) && (species === "ALL" || pet.species === species)), [profiles, intent, species]);
  const profile = filtered.length ? filtered[index % filtered.length] : null;
  function next() { setIndex((value) => value + 1); }
  function dismissEvaluated(id: string) { setProfiles((all) => all.filter((item) => item.id !== id)); }
  async function loadMoreProfiles() {
    if (!viewerPetId) { setNotice("Cadastre um pet para descobrir perfis reais."); return; }
    try {
      const response = await fetch(`${api}/api/pets/explore?viewerPetId=${encodeURIComponent(viewerPetId)}&limit=50&radiusKm=${radiusKm}`, { credentials:"include" });
      if (!response.ok) throw new Error("Não foi possível buscar novos perfis.");
      const data = await response.json() as ApiPet[];
      const known = new Set(profiles.map((item) => item.id));
      const fresh = data.map(mapApiPet).filter((item) => !known.has(item.id));
      setProfiles((all) => all.filter((item) => !item.demo).concat(fresh)); setUsingDemo(false); setIndex(0);
      if (!fresh.length) setNotice("Você já avaliou todos os perfis disponíveis nesta região. Tente novamente mais tarde.");
    } catch (error) { setNotice((error as Error).message); }
  }
  function changeIntent(value: "ALL" | Intent) { setIntent(value); setIndex(0); }
  function changeSpecies(value: string) { setSpecies(value); setIndex(0); }
  function openProfile(pet = profile) { if (!pet) return; if (pet.demo) setProfilePreview(pet); else router.push(`/pet/perfil?petId=${encodeURIComponent(pet.id)}`); }
  function resetCard() { pointerStart.current = null; const card = cardRef.current; if (!card) return; card.style.removeProperty("--swipe-x"); card.style.removeProperty("--swipe-y"); card.style.removeProperty("--swipe-rotation"); delete card.dataset.swipeDirection; delete card.dataset.dragging; }
  function handlePointerStart(event: PointerEvent<HTMLElement>) {
    if (actionBusy || !event.isPrimary || (event.pointerType === "mouse" && event.button !== 0) || (event.target as HTMLElement).closest("button,a")) return;
    pointerStart.current = { x: event.clientX, y: event.clientY, id: event.pointerId };
    event.currentTarget.setPointerCapture(event.pointerId);
    if (cardRef.current) cardRef.current.dataset.dragging = "true";
  }
  function handlePointerMove(event: PointerEvent<HTMLElement>) {
    const start = pointerStart.current, card = cardRef.current;
    if (!start || !card || start.id !== event.pointerId) return;
    const x = event.clientX - start.x, y = event.clientY - start.y;
    card.style.setProperty("--swipe-x", `${x * .6}px`); card.style.setProperty("--swipe-y", `${y * .35}px`); card.style.setProperty("--swipe-rotation", `${x / 35}deg`);
    card.dataset.swipeDirection = Math.max(Math.abs(x), Math.abs(y)) < 30 ? "" : Math.abs(x) > Math.abs(y) ? x > 0 ? "like" : "pass" : y > 0 ? "profile" : "super";
  }
  function handlePointerEnd(event: PointerEvent<HTMLElement>) {
    const start = pointerStart.current;
    if (!start || start.id !== event.pointerId) return;
    const x = event.clientX - start.x, y = event.clientY - start.y;
    resetCard();
    if (Math.max(Math.abs(x), Math.abs(y)) < 75 || actionBusy) return;
    if (Math.abs(x) > Math.abs(y)) { if (x < 0) void pass(); else void like(); }
    else if (y > 0) openProfile(); else if (profile?.intent !== "ADOPTION") void like(true);
  }

  async function pass() {
    if (!profile || actionBusy) return;
    if (profile.demo) { next(); return; }
    if (!viewerPetId) { setNotice("Cadastre um pet antes de avaliar perfis."); return; }
    setActionBusy(true);
    try {
      const response = await fetch(`${api}/api/pets/${encodeURIComponent(profile.id)}/pass`, { method: "POST", credentials: "include", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ fromPetId: viewerPetId }) });
      const result = await response.json();
      if (!response.ok) throw new Error(result.message ?? "Não foi possível avaliar este perfil.");
      dismissEvaluated(profile.id);
    } catch (error) { setNotice((error as Error).message); } finally { setActionBusy(false); }
  }

  async function like(superMatch = false) {
    if (!profile) return;
    if (actionBusy) return;
    if (profile.intent === "ADOPTION") { setModal(profile); setApplicationSent(false); setApplicationError(""); return; }
    void petFeedback("tap");
    if (profile.demo) {
      if (superMatch) { setNotice("Super Match demonstrativo. Cadastre um perfil para usar a funcionalidade."); next(); return; }
      if (profile.intent === "RESPONSIBLE_BREEDING") setNotice("Relacionamentos exigem análise humana e verificação de saúde; a pontuação não recomenda reprodução.");
      else if (profile.mutual) { void petFeedback("match"); setMatches((old) => old.some((item) => item.id === profile.id) ? old : [profile, ...old]); setNotice(`Você e ${profile.name} demonstraram interesse nesta prévia.`); }
      else setNotice(`Interesse demonstrado por ${profile.name} nesta prévia.`);
      next();
      return;
    }
    if (!viewerPetId) { setNotice("Cadastre um pet antes de demonstrar interesse."); return; }
    try {
      setActionBusy(true);
      const response = await fetch(`${api}/api/pets/${encodeURIComponent(profile.id)}/${superMatch ? "super-match" : "interest"}`, { method: "POST", credentials: "include", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ fromPetId: viewerPetId }) });
      const result = await response.json();
      if (!response.ok) throw new Error(Array.isArray(result.message) ? result.message.join(" ") : result.message ?? "Não foi possível enviar o interesse.");
      if (result.matched) { void petFeedback("match"); setMatches((old) => [profile, ...old]); setMatchCelebration(profile); setNotice(`Match com ${profile.name}!`); }
      else if (result.reviewRequired) setNotice("Interesse registrado para revisão humana. Ainda são necessárias verificações de saúde e bem-estar.");
      else setNotice(result.like?.isSuperMatch ? "Super Match enviado! O tutor receberá uma notificação especial." : "Interesse enviado. Se os dois tutores demonstrarem interesse, haverá um match.");
      dismissEvaluated(profile.id);
    } catch (error) { setNotice((error as Error).message); } finally { setActionBusy(false); }
  }

  async function apply(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!modal) return;
    const formData = new FormData(event.currentTarget);
    const message = String(formData.get("message") ?? "");
    const livingDetails = String(formData.get("livingDetails") ?? "");
    if (modal.demo) { void petFeedback("success"); setApplicationSent(true); return; }
    try {
      const response = await fetch(`${api}/api/pets/${encodeURIComponent(modal.id)}/adoption-applications`, { method: "POST", credentials: "include", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ message, livingDetails }) });
      const result = await response.json();
      if (!response.ok) throw new Error(Array.isArray(result.message) ? result.message.join(" ") : result.message ?? "Não foi possível enviar a candidatura.");
      void petFeedback("success"); setApplicationSent(true);
    } catch (error) { setApplicationError((error as Error).message); }
  }

  async function reportProfile(pet: Profile) {
    if (pet.demo) { setNotice("Os perfis demonstrativos não são usuários reais e não podem ser denunciados."); return; }
    const reason = window.prompt("Por que você quer denunciar este perfil?", "Informação ou comportamento inadequado");
    if (!reason?.trim()) return;
    try {
      const response = await fetch(`${api}/api/safety/reports`, { method:"POST", credentials:"include", headers:{"Content-Type":"application/json"}, body:JSON.stringify({targetType:"PET", targetId:pet.id, reason:reason.trim()}) });
      const result = await response.json();
      if (!response.ok) throw new Error(result.message ?? "Não foi possível enviar a denúncia.");
      setNotice("Denúncia enviada para análise.");
    } catch (error) { setNotice((error as Error).message); }
  }

  async function blockProfile(pet: Profile) {
    if (pet.demo) { setNotice("Os perfis demonstrativos não são usuários reais e não podem ser bloqueados."); return; }
    if (!window.confirm(`Bloquear o tutor de ${pet.name}? O perfil será removido da sua descoberta.`)) return;
    try {
      const response = await fetch(`${api}/api/safety/pets/${encodeURIComponent(pet.id)}/block`, { method:"POST", credentials:"include" });
      const result = await response.json();
      if (!response.ok) throw new Error(result.message ?? "Não foi possível bloquear este perfil.");
      setProfiles((all) => all.filter((item) => item.id !== pet.id)); setIndex(0); setNotice("Perfil bloqueado.");
    } catch (error) { setNotice((error as Error).message); }
  }

  return <div className="explore-page">
    <span className="sr-only" id="explore-gesture-help">Arraste a foto ou use as setas: esquerda para passar, direita para demonstrar interesse, cima para Super Match, baixo para ver o perfil.</span>
    <Dialog open={compatibilityOpen} onClose={() => setCompatibilityOpen(false)} title="Como ler a compatibilidade" description="Os fatores resumem semelhanças entre os perfis e ajudam a descobrir novas conexões."><p>Espécie, objetivo, região aproximada, porte, idade e comportamento contribuem para o resultado. A pontuação não garante afinidade ou segurança.</p><p>Para reprodução, a pontuação não gera recomendação automática: são necessárias verificações de saúde, bem-estar e revisão humana.</p></Dialog>
    <div className="explore-heading"><h1 className="product-h1">Explore com <em>carinho.</em></h1><button className="explore-filter-button" aria-label="Abrir preferências" aria-expanded={preferencesOpen} title="Preferências" onClick={() => setPreferencesOpen((open) => !open)}><Filter size={18}/></button></div>
    {usingDemo && <div className="demo-notice"><Info size={15}/><span>Prévia da descoberta · estes perfis são exemplos e não representam usuários cadastrados.</span></div>}
    <div className="explore-layout"><section className="explore-main">
      {preferencesOpen && <div className="explore-preferences-panel" id="explore-filters"><div className="intent-tabs" role="group" aria-label="Objetivo do encontro">{[{id:"ALL",label:"Tudo"},{id:"FRIENDSHIP",label:"Amizade"},{id:"RESPONSIBLE_BREEDING",label:"Relacionamento"},{id:"ADOPTION",label:"Adoção"}].map((item) => <button key={item.id} className={intent === item.id ? "intent-tab-active" : ""} onClick={() => changeIntent(item.id as "ALL" | Intent)}>{item.label}</button>)}</div><label className="species-select"><PawPrint size={14}/><select value={species} onChange={(event) => changeSpecies(event.target.value)} aria-label="Filtrar espécie"><option value="ALL">Cães e gatos</option><option value="Cão">Cães</option><option value="Gato">Gatos</option><option value="Outro">Outras espécies</option></select><ChevronDown size={13}/></label><label className="region-filter"><MapPin size={14}/><span>Até</span><select value={radiusKm} onChange={(event)=>setRadiusKm(Number(event.target.value))} aria-label="Distância máxima"><option value={10}>10 km</option><option value={25}>25 km</option><option value={50}>50 km</option><option value={100}>100 km</option><option value={200}>200 km</option></select></label></div>}
      {ownPets.length > 0 && <label className="viewer-pet-select">Explorando com <select value={viewerPetId} onChange={(event) => setViewerPetId(event.target.value)}>{ownPets.map((pet) => <option key={pet.id} value={pet.id}>{pet.name}</option>)}</select><ChevronDown size={13}/></label>}
      {notice && <div className="explore-notice" role="status">{notice}<button onClick={() => setNotice("")} aria-label="Dispensar aviso"><X size={13}/></button></div>}
      {loading ? <div className="home-loading" role="status"><span className="session-spinner"/>Encontrando novos focinhos…</div> : error ? <div className="ma-error-state" role="alert"><h2>Vamos tentar de novo?</h2><p>{error}</p><Button onClick={() => setAttempt((value) => value + 1)}>Tentar novamente</Button></div> : profile ? <><article ref={cardRef} aria-busy={actionBusy} className="explore-card"><div className="explore-photo" tabIndex={0} aria-describedby="explore-gesture-help" onPointerDown={handlePointerStart} onPointerMove={handlePointerMove} onPointerUp={handlePointerEnd} onPointerCancel={resetCard} onKeyDown={(event) => { if (event.target !== event.currentTarget || actionBusy) return; if (event.key === "ArrowLeft") { event.preventDefault(); void pass(); } if (event.key === "ArrowRight") { event.preventDefault(); void like(); } if (event.key === "ArrowUp" && profile.intent !== "ADOPTION") { event.preventDefault(); void like(true); } if (event.key === "ArrowDown") { event.preventDefault(); openProfile(); } }} role="group" aria-label={profile.photoUrl || profile.demo ? `Foto ${profile.demo ? "demonstrativa " : ""}de ${profile.name}` : `Foto de ${profile.name} ainda não publicada`} style={{ backgroundImage: profile.photoUrl ? `linear-gradient(180deg,#17231c28 0%,transparent 34%,#17231cce 100%),url(${profile.photoUrl})` : profile.demo ? `linear-gradient(180deg,#17231c28 0%,transparent 34%,#17231cce 100%),url(https://images.unsplash.com/${profile.photo}?auto=format&fit=crop&w=1200&q=88)` : "linear-gradient(160deg,#e8eee4,#dfe8db)" }}><div className="explore-photo-top"><span className="intent-badge"><span/> {intentLabels[profile.intent]}</span><button aria-label="Denunciar este perfil" onClick={() => void reportProfile(profile)}><span>•••</span></button><button aria-label="Bloquear este perfil" onClick={() => void blockProfile(profile)}><Ban size={14}/></button></div><div className="explore-photo-bottom">{profile.intent === "FRIENDSHIP" && profile.score !== null && <span className="compatibility-badge"><Sparkles size={12}/>{profile.score}% compatível</span>}{profile.intent === "RESPONSIBLE_BREEDING" && <span className="breeding-review-badge"><ShieldCheck size={12}/> Revisão humana obrigatória</span>}<h2>{profile.name} <span>· {profile.age}</span></h2><div className="explore-pet-meta">{profile.breed}<i/> {profile.sex}<i/> Porte {profile.size}</div></div><span className="swipe-cue swipe-cue-like">SIM</span><span className="swipe-cue swipe-cue-pass">AGORA NÃO</span><span className="swipe-cue swipe-cue-super">SUPER MATCH</span><span className="swipe-cue swipe-cue-profile">VER PERFIL</span></div><div className="explore-card-body"><div className="explore-location"><MapPin size={14}/><strong>{profile.distance}</strong><i/> {profile.city}</div><p className="explore-bio">{profile.note}</p><div className="explore-traits">{profile.traits.map((trait) => <span key={trait}>{trait}</span>)}</div>{profile.health && <div className="health-status"><ShieldCheck size={14}/><span>Informações de saúde declaradas pelo tutor</span><button aria-label="Sobre informações de saúde" onClick={() => setNotice("Informações declaradas não substituem documentos ou avaliação veterinária.")}><Info size={13}/></button></div>}{profile.intent === "RESPONSIBLE_BREEDING" && <div className="breeding-warning"><ShieldCheck size={14}/><span>Compatibilidade não é calculada para reprodução. Exige verificação independente de saúde e bem-estar.</span></div>}{profile.demo ? <button className="full-profile-link" onClick={() => setProfilePreview(profile)}>Ver perfil completo <ArrowRight size={14}/></button> : <Link className="full-profile-link" href={`/pet/perfil?petId=${encodeURIComponent(profile.id)}`}>Ver perfil completo <ArrowRight size={14}/></Link>}</div></article>
        <div className="explore-actions">{profile.intent === "ADOPTION" ? <><button className="skip-action" onClick={() => void pass()} aria-label="Ver próximo perfil" disabled={actionBusy}><X size={21}/></button><button className="adoption-action" onClick={() => void like()} disabled={actionBusy}>Tenho interesse em adotar <ArrowRight size={16}/></button></> : <><button className="skip-action" onClick={() => void pass()} aria-label="Passar perfil" disabled={actionBusy}><X size={21}/></button><button className="like-action" onClick={() => void like()} aria-label="Curtir perfil" disabled={actionBusy}><Heart size={19}/></button><button className="super-match-action" onClick={() => void like(true)} aria-label="Enviar Super Match" disabled={actionBusy}><Sparkles size={17}/></button><button className="skip-action" onClick={() => setCompatibilityOpen(true)} aria-label="Ver fatores de compatibilidade"><Info size={17}/></button></>}</div><p className="explore-footnote">{profile.intent === "ADOPTION" ? "A adoção segue um processo de candidatura e avaliação do responsável." : "Um match só acontece com interesse mútuo entre tutores."}</p></> : <div className="explore-empty"><PetFriends mood="friends"/><h2>Nenhum perfil por aqui ainda.</h2><p>Altere os filtros ou volte mais tarde para conhecer novos pets.</p>{usingDemo ? <button onClick={() => { setIntent("ALL"); setSpecies("ALL"); setIndex(0); }}>Limpar filtros</button> : <button onClick={() => void loadMoreProfiles()}>Buscar mais perfis</button>}</div>}
    </section>
    <aside className="explore-aside"><div className="aside-title"><h2>Compatibilidade</h2><button aria-label="Como calculamos" onClick={() => setCompatibilityOpen(true)}><Info size={14}/></button></div><p className="aside-intro">Uma explicação clara do que pode contribuir para uma boa conexão.</p><div className="factor-list">{[{name:"Espécie compatível",value:"25%",width:"25%"},{name:"Objetivos em comum",value:"20%",width:"20%"},{name:"Proximidade aproximada",value:"20%",width:"20%"},{name:"Porte e idade",value:"20%",width:"20%"},{name:"Comportamento e interesses",value:"15%",width:"15%"}].map((factor) => <div className="factor" key={factor.name}><div><span>{factor.name}</span><small>{factor.value}</small></div><i><b style={{width:factor.width}}/></i></div>)}</div><div className="factor-caption"><Info size={13}/><span>Pesos explicáveis; a pontuação ajuda a explorar, não determina a qualidade ou segurança de um encontro.</span></div><div className="aside-divider"/><div className="match-aside-title"><div><Heart size={16}/><h3>Seus matches</h3></div><span>{matches.length}</span></div>{matches.length ? <div className="mini-match-list">{matches.map((match) => <button className="mini-match" key={match.id} onClick={() => openProfile(match)} aria-label={`Ver perfil de ${match.name}`}><div className="mini-match-photo" style={{backgroundImage:`url(${match.photoUrl || `https://images.unsplash.com/${match.photo}?auto=format&fit=crop&w=100&q=80`})`}}/><div><strong>{match.name}</strong><small>{match.demo ? "Match de demonstração" : "Interesse mútuo"}</small></div><Check size={15}/></button>)}</div> : <div className="match-empty-state"><div><Heart size={17}/></div><p>Quando o interesse é mútuo, uma nova conexão começa aqui.</p></div>}<div className="safe-reminder"><ShieldCheck size={16}/><div><strong>Combine com cuidado</strong><p>Conversem antes, encontrem-se em local público e protejam os dados pessoais.</p></div></div></aside></div>
    {profilePreview && <div className="dialog-backdrop" role="presentation" onClick={() => setProfilePreview(null)}><section ref={previewRef} className="product-dialog" role="dialog" aria-modal="true" aria-labelledby="pet-preview-title" onClick={(event) => event.stopPropagation()}><button className="dialog-close" onClick={() => setProfilePreview(null)} aria-label="Fechar"><X size={18}/></button><div className="dialog-eyebrow">PERFIL DO PET · PRÉVIA</div><h2 id="pet-preview-title">{profilePreview.name}, {profilePreview.age}</h2><p className="dialog-lead">{profilePreview.breed} · {profilePreview.sex} · Porte {profilePreview.size}</p><div className="dialog-factor"><MapPin size={16}/><span>{profilePreview.distance} · {profilePreview.city}</span></div><p className="dialog-lead">{profilePreview.note}</p><div className="explore-traits">{profilePreview.traits.map((trait) => <span key={trait}>{trait}</span>)}</div><button className="dialog-understood" onClick={() => setProfilePreview(null)}>Voltar aos perfis</button></section></div>}
    {matchCelebration && <div className="dialog-backdrop" role="presentation" onClick={() => setMatchCelebration(null)}><section ref={celebrationRef} className="match-celebration" role="dialog" aria-modal="true" aria-labelledby="match-celebration-title" onClick={(event) => event.stopPropagation()}><button className="dialog-close" onClick={() => setMatchCelebration(null)} aria-label="Fechar"><X size={18}/></button><div className="match-celebration-pets"><span style={ownPets.find((pet) => pet.id === viewerPetId)?.coverPhotoUrl ? {backgroundImage:`url(${ownPets.find((pet) => pet.id === viewerPetId)?.coverPhotoUrl})`} : undefined}>{ownPets.find((pet) => pet.id === viewerPetId)?.name?.slice(0,1) ?? "🐾"}</span><i><Heart size={15} fill="currentColor"/></i><span style={matchCelebration.photoUrl ? {backgroundImage:`url(${matchCelebration.photoUrl})`} : undefined}>{matchCelebration.name.slice(0,1)}</span></div><div className="dialog-eyebrow">UMA NOVA CONEXÃO</div><h2 id="match-celebration-title">Deu Match!</h2><p>Uma nova amizade está começando.</p><div className="match-celebration-names">{ownPets.find((pet) => pet.id === viewerPetId)?.name ?? "Seu pet"}<Heart size={12}/>{matchCelebration.name}</div><Link href="/mensagens" className="match-celebration-primary" onClick={() => setMatchCelebration(null)}>Enviar uma mensagem <ArrowRight size={15}/></Link><button className="match-celebration-secondary" onClick={() => { setMatchCelebration(null); }}>Continuar explorando</button></section></div>}
    {modal && (
      <div className="dialog-backdrop" role="presentation" onClick={() => setModal(null)}>
        <section ref={modalRef} className="product-dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title" onClick={(event) => event.stopPropagation()}>
          <button className="dialog-close" onClick={() => setModal(null)} aria-label="Fechar"><X size={18}/></button>
          {modal.intent === "ADOPTION" ? (
            applicationSent ? (
              <div className="application-success">
                <span><Check size={22}/></span>
                <h2 id="dialog-title">Candidatura enviada.</h2>
                <p>{modal.demo ? "Nesta prévia, a candidatura foi simulada." : "O responsável pelo animal receberá sua candidatura para avaliação."}</p>
                <button onClick={() => setModal(null)}>Entendi</button>
              </div>
            ) : (
              <>
                <div className="dialog-eyebrow">CANDIDATURA DE ADOÇÃO</div>
                <h2 id="dialog-title">Quer conhecer {modal.name}?</h2>
                <p className="dialog-lead">A adoção não depende de curtida mútua. Conte um pouco sobre o lar que você pode oferecer.</p>
                <form className="application-form" onSubmit={(event) => void apply(event)}>
                  <label>Como é sua rotina?<textarea name="message" required minLength={20} maxLength={1500} placeholder="Conte sobre o tempo e o cuidado que você pode oferecer..."/></label>
                  <label>Como é o espaço onde o pet vai viver?<textarea name="livingDetails" required maxLength={1000} placeholder="Conte um pouco sobre o ambiente e quem mora com você..."/></label>
                  <label><input type="checkbox" required/> Entendo que a candidatura será avaliada pelo responsável pelo animal.</label>
                  {applicationError && <div className="form-alert" role="alert">{applicationError}</div>}
                  <button>Enviar candidatura <ArrowRight size={15}/></button>
                </form>
              </>
            )
          ) : (
            <>
              <div className="dialog-eyebrow">COMO LER A COMPATIBILIDADE</div>
              <h2 id="dialog-title">Uma pista, não uma promessa.</h2>
              <p className="dialog-lead">Os fatores exibidos resumem semelhanças de perfil. Eles não garantem afinidade, saúde ou segurança.</p>
              <div className="dialog-factor"><PawPrint size={16}/><span>Espécie, porte e idade ajudam a contextualizar a rotina.</span></div>
              <div className="dialog-factor"><MapPin size={16}/><span>Usamos região aproximada; o endereço residencial nunca é exibido.</span></div>
              <div className="dialog-factor"><ShieldCheck size={16}/><span>Para reprodução, pontuação nunca gera recomendação automática. É necessária verificação de saúde e avaliação humana.</span></div>
              <button className="dialog-understood" onClick={() => setModal(null)}>Entendi</button>
            </>
          )}
        </section>
      </div>
    )}
  </div>;
}

"use client";

import dynamic from "next/dynamic";
import { useId, useState, type KeyboardEvent } from "react";
import { ChevronDown, LoaderCircle, LocateFixed, Map, MapPin, Search, ShieldCheck } from "lucide-react";
import { Capacitor } from "@capacitor/core";
import { Geolocation } from "@capacitor/geolocation";
import { petFeedback } from "@/lib/native-feedback";

export type LocationSelection = { city: string; state: string; latitude: number; longitude: number };
const LocationMap = dynamic(() => import("./location-picker-map"), { ssr: false, loading: () => <div className="location-map-loading" role="status"><LoaderCircle className="form-spinner" size={20} aria-hidden="true" /> Carregando mapa…</div> });
const privacyRound = (value: number) => Math.round(value * 100) / 100;
const api = process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:4000";

function parseLocation(value: unknown): LocationSelection {
  if (!value || typeof value !== "object") throw new Error("Não encontramos essa região. Tente o nome da cidade e a sigla do estado.");
  const point = value as Partial<LocationSelection>;
  if (typeof point.city !== "string" || typeof point.state !== "string" || typeof point.latitude !== "number" || typeof point.longitude !== "number" || !Number.isFinite(point.latitude) || !Number.isFinite(point.longitude)) throw new Error("Não encontramos essa região. Tente o nome da cidade e a sigla do estado.");
  return { city: point.city, state: point.state, latitude: privacyRound(point.latitude), longitude: privacyRound(point.longitude) };
}

export function LocationPicker({ onSelect, initial }: { onSelect: (location: LocationSelection) => void; initial?: Partial<LocationSelection> }) {
  const id = useId();
  const [query, setQuery] = useState("");
  const [location, setLocation] = useState<LocationSelection | null>(initial?.latitude != null && initial.longitude != null && initial.city && initial.state ? { city: initial.city, state: initial.state, latitude: initial.latitude, longitude: initial.longitude } : null);
  const [mapOpen, setMapOpen] = useState(false);
  const [busy, setBusy] = useState<"gps" | "search" | "map" | null>(null);
  const [error, setError] = useState("");
  const center: [number, number] = location ? [location.latitude, location.longitude] : [-14.235, -51.925];

  function selectLocation(selected: LocationSelection) {
    setLocation(selected); onSelect(selected); setQuery(`${selected.city}, ${selected.state}`); setMapOpen(true); setError(""); void petFeedback("success");
  }

  async function reverse(latitude: number, longitude: number) {
    const lat = privacyRound(latitude); const lon = privacyRound(longitude);
    const response = await fetch(`${api}/api/location/reverse?lat=${lat}&lon=${lon}`);
    if (!response.ok) throw new Error("Não foi possível localizar essa região. Busque pelo nome da cidade.");
    selectLocation({ ...parseLocation(await response.json()), latitude: lat, longitude: lon });
  }

  function failure(cause: unknown, fallback: string) { setError(cause instanceof TypeError ? "Não conseguimos conectar à busca de localização. Você pode informar cidade e estado manualmente." : cause instanceof Error ? cause.message : fallback); }

  async function search() {
    if (query.trim().length < 3 || busy) return;
    setBusy("search"); setError("");
    try {
      const response = await fetch(`${api}/api/location/search?q=${encodeURIComponent(query.trim())}`);
      if (!response.ok) throw new Error(response.status === 404 ? "Local não encontrado. Tente o nome da cidade e a sigla do estado." : "A busca está indisponível no momento. Tente novamente ou preencha cidade e estado.");
      selectLocation(parseLocation(await response.json()));
    } catch (cause) { failure(cause, "Não foi possível buscar sua região."); }
    finally { setBusy(null); }
  }

  async function useDeviceLocation() {
    if (busy) return;
    setBusy("gps"); setError("");
    try {
      let coords: { latitude: number; longitude: number };
      if (Capacitor.isNativePlatform()) {
        let permissions = await Geolocation.checkPermissions();
        if (permissions.location !== "granted" && permissions.coarseLocation !== "granted") permissions = await Geolocation.requestPermissions({ permissions: ["coarseLocation"] });
        if (permissions.location !== "granted" && permissions.coarseLocation !== "granted") throw new Error("Permita a localização nas configurações do aparelho ou busque sua cidade.");
        coords = (await Geolocation.getCurrentPosition({ enableHighAccuracy: false, timeout: 12000, maximumAge: 300000 })).coords;
      } else {
        if (!navigator.geolocation) throw new Error("Este navegador não disponibilizou a localização. Busque sua cidade.");
        coords = await new Promise((resolve, reject) => navigator.geolocation.getCurrentPosition(({ coords: point }) => resolve(point), (cause) => reject(new Error(cause.code === 1 ? "O acesso ao GPS não foi permitido. Você pode buscar sua cidade sem usar a localização do aparelho." : "Não conseguimos acessar o GPS. Tente novamente ou busque sua cidade.")), { enableHighAccuracy: false, timeout: 12000, maximumAge: 300000 }));
      }
      await reverse(coords.latitude, coords.longitude);
    } catch (cause) { failure(cause, "Não conseguimos acessar o GPS. Busque sua cidade."); }
    finally { setBusy(null); }
  }

  async function selectPoint(latitude: number, longitude: number) {
    if (busy) return;
    setBusy("map"); setError("");
    try { await reverse(latitude, longitude); }
    catch (cause) { failure(cause, "Não foi possível selecionar essa região."); }
    finally { setBusy(null); }
  }

  function handleSearchKey(event: KeyboardEvent<HTMLInputElement>) { if (event.key === "Enter") { event.preventDefault(); void search(); } }
