"use client";

import Link from "next/link";
import { useEffect, useState } from "react";
import { ArrowRight, ArrowUpRight, Bell, Heart, LoaderCircle, MessageCircle, PawPrint, Plus, Search, Settings2, ShieldCheck, Sparkles } from "lucide-react";
import { Button } from "@/components/ui/button";
import { PetPhotosManager } from "@/components/pet-photos-manager";

export function DashboardView() {
  const [summary,setSummary]=useState({name:"tutor",pets:0,matches:0,conversations:0,notifications:0});
  useEffect(()=>{let active=true;const api=process.env.NEXT_PUBLIC_API_URL??"http://localhost:4000";void Promise.all([fetch(`${api}/api/auth/me`,{credentials:"include"}),fetch(`${api}/api/pets/mine`,{credentials:"include"}),fetch(`${api}/api/pets/matches`,{credentials:"include"}),fetch(`${api}/api/chat/conversations`,{credentials:"include"}),fetch(`${api}/api/notifications/unread-count`,{credentials:"include"})]).then(async([me,pets,matches,chats,notifications])=>{const [u,p,m,c,n]=await Promise.all([me.ok?me.json():null,pets.ok?pets.json():[],matches.ok?matches.json():[],chats.ok?chats.json():[],notifications.ok?notifications.json():{count:0}]);if(active)setSummary({name:u?.tutor?.displayName?.split(" ")[0]??"tutor",pets:p.length,matches:m.length,conversations:c.length,notifications:n.count});}).catch(()=>undefined);return()=>{active=false;};},[]);
  const steps=[{n:"01",title:"Complete seu perfil de tutor",done:true},{n:"02",title:"Cadastre seu primeiro animal",done:summary.pets>0},{n:"03",title:"Escolha o que vocês procuram",done:summary.pets>0}];
  return <div className="dashboard-view"><div className="dashboard-welcome"><div><div className="product-eyebrow"><span><Sparkles size={13}/></span> UM BOM DIA PARA SE CONECTAR</div><h1 className="product-h1">Olá, {summary.name}. <em>Que bom ver você.</em></h1><p className="product-lead">Um dia bonito para conhecer novos focinhos por aí.</p></div><Button asChild><Link href="/explorar">Explorar pets <ArrowRight size={15}/></Link></Button></div><div className="dashboard-grid"><Link href="/animais/novo" className="first-pet-card"><span className="first-pet-icon"><PawPrint size={20}/></span><span className="first-pet-kicker">SEU ESPAÇO COMEÇA AQUI</span><h2>Apresente seu<br/>melhor amigo.</h2><p>Crie o perfil dele e encontre pessoas e pets com afinidades.</p><span className="first-pet-cta">{summary.pets?`Gerenciar ${summary.pets} ${summary.pets===1?"animal":"animais"}`:"Cadastrar primeiro pet"} <ArrowUpRight size={15}/></span><div className="first-pet-watermark"><PawPrint size={96}/></div></Link><div className="summary-card"><div className="summary-top"><span>CONEXÕES</span><span><Heart size={16}/></span></div><strong>{summary.matches}</strong><p>Seu próximo match pode começar com um oi.</p><Link href="/matches">Ver matches <ArrowRight size={14}/></Link></div><div className="summary-card"><div className="summary-top"><span>CONVERSAS</span><span><MessageCircle size={16}/></span></div><strong>{summary.conversations}</strong><p>As conversas aparecem depois de um match.</p><Link href="/mensagens">Abrir mensagens <ArrowRight size={14}/></Link></div><div className="dashboard-guide"><div className="guide-header"><div><span>PRÓXIMOS PASSOS</span><h2>Deixe tudo pronto para descobrir</h2></div><Settings2 size={17}/></div>{steps.map((step)=><div className="guide-step" key={step.n}><span className={step.done?"guide-done":""}>{step.done?"✓":step.n}</span><p>{step.title}</p>{!step.done&&<ArrowRight size={15}/>}</div>)}</div><div className="responsibility-card"><ShieldCheck size={18}/><div><span>UM LEMBRETE DO MATCHANIMAL</span><p>{summary.notifications?`Você tem ${summary.notifications} atualizações para ver.`:"Respeite sempre o tempo, os limites e o bem-estar de cada animal."}</p><Link href={summary.notifications?"/notificacoes":"/seguranca"}>{summary.notifications?"Ver notificações":"Nosso compromisso com cuidado"} <ArrowRight size={13}/></Link></div></div></div><div className="dashboard-section-title"><div><span>PARA DESCOBRIR</span><h2>Novos amigos por perto</h2></div><Link href="/explorar">Ver todos <ArrowRight size={14}/></Link></div><DashboardRecommendations hasPets={summary.pets>0}/></div>;
}

type DashboardSuggestion={id:string;name:string;breed:string|null;species:string;city:string|null;state:string|null;coverPhotoUrl:string|null;compatibility?:{score?:number|null}|null};
function DashboardRecommendations({hasPets}:{hasPets:boolean}){const[suggestions,setSuggestions]=useState<DashboardSuggestion[]>([]);const[loading,setLoading]=useState(hasPets);useEffect(()=>{let active=true;const api=process.env.NEXT_PUBLIC_API_URL??"http://localhost:4000";if(!hasPets){setLoading(false);return()=>{active=false;};}void fetch(`${api}/api/pets/mine`,{credentials:"include"}).then(async(response)=>response.ok?await response.json() as {id:string}[]:[]).then(async(pets)=>{if(!pets[0])return[];const response=await fetch(`${api}/api/pets/explore?viewerPetId=${encodeURIComponent(pets[0].id)}&limit=3&radiusKm=50`,{credentials:"include"});return response.ok?await response.json() as DashboardSuggestion[]:[];}).then((result)=>{if(active)setSuggestions(result);}).catch(()=>undefined).finally(()=>{if(active)setLoading(false);});return()=>{active=false;};},[hasPets]);if(loading)return <div className="dashboard-discover"><div className="discover-placeholder"><span className="session-spinner"/><p>Buscando perfis compatíveis na sua região…</p></div></div>;if(!hasPets||!suggestions.length)return <div className="dashboard-discover"><div className="discover-placeholder"><PawPrint size={20}/><p>{hasPets?"Não encontramos perfis compatíveis nesta região ainda.":"Cadastre seu primeiro animal para começar a explorar."}</p><Link href={hasPets?"/explorar":"/animais/novo"}>{hasPets?"Ajustar raio e filtros":"Cadastrar animal"} <ArrowRight size={14}/></Link></div></div>;return <div className="dashboard-suggestions">{suggestions.map((pet)=><Link href={`/pet/perfil?petId=${encodeURIComponent(pet.id)}`} className="dashboard-suggestion" key={pet.id}><span className="dashboard-suggestion-photo" style={pet.coverPhotoUrl?{backgroundImage:`url(${pet.coverPhotoUrl})`}:{}}><PawPrint size={18}/></span><span className="dashboard-suggestion-copy"><strong>{pet.name}</strong><small>{pet.breed??pet.species} · {[pet.city,pet.state].filter(Boolean).join(", ")}</small></span>{pet.compatibility?.score!=null&&<b>{pet.compatibility.score}%</b>}</Link>)}</div>}

type MyPetPhoto={id:string;storageKey:string;url:string;sortOrder:number;altText:string|null;moderation:string};
type MyPet={id:string;name:string;species:string;speciesOther?:string|null;breed?:string|null;intent:string;isPublic:boolean;coverPhotoUrl?:string|null;photos:MyPetPhoto[]};
export function MyPetsView() {
  const [pets,setPets]=useState<MyPet[]>([]);const [loading,setLoading]=useState(true);const [visibilityBusy,setVisibilityBusy]=useState("");const [visibilityError,setVisibilityError]=useState("");
  useEffect(()=>{let active=true;fetch(`${process.env.NEXT_PUBLIC_API_URL??"http://localhost:4000"}/api/pets/mine`,{credentials:"include"}).then(async(response)=>{if(!response.ok)throw new Error("Não foi possível carregar seus animais. Tente novamente.");const result=await response.json() as MyPet[];if(active)setPets(result);}).catch((cause)=>{if(active)setVisibilityError(cause instanceof Error?cause.message:"Não foi possível carregar seus animais.");}).finally(()=>{if(active)setLoading(false);});return()=>{active=false;};},[]);
  async function refreshPets(){const response=await fetch(`${process.env.NEXT_PUBLIC_API_URL??"http://localhost:4000"}/api/pets/mine`,{credentials:"include"});if(response.ok)setPets(await response.json() as MyPet[]);}
  async function toggleVisibility(pet:MyPet){setVisibilityBusy(pet.id);setVisibilityError("");try{const response=await fetch(`${process.env.NEXT_PUBLIC_API_URL??"http://localhost:4000"}/api/pets/${encodeURIComponent(pet.id)}/visibility`,{method:"PATCH",credentials:"include",headers:{"Content-Type":"application/json"},body:JSON.stringify({isPublic:!pet.isPublic})});const result=await response.json();if(!response.ok)throw new Error(result.message??"Não foi possível atualizar a visibilidade.");setPets((all)=>all.map((item)=>item.id===pet.id?{...item,isPublic:result.isPublic}:item));}catch(error){setVisibilityError((error as Error).message);}finally{setVisibilityBusy("");}}
  if(loading)return <div className="profile-loading"><span className="session-spinner"/> Carregando seus animais...</div>;
  if(visibilityError&&!pets.length)return <div className="ma-flow-error" role="alert"><PawPrint size={28}/><h1>Seus animais não carregaram</h1><p>{visibilityError}</p><button type="button" onClick={()=>window.location.reload()}>Tentar novamente</button></div>;
  if(pets.length)return <div className="my-pets-view"><div className="my-pets-heading"><div><div className="product-eyebrow"><span><PawPrint size={13}/></span> SEU TIME DE QUATRO PATAS</div><h1 className="product-h1">Seus <em>companheiros.</em></h1><p className="product-lead">Você controla a visibilidade e o tipo de conexão de cada animal.</p></div><div className="my-pets-actions"><Button variant="outline" asChild><Link href="/adocoes">Adoções</Link></Button><Button asChild><Link href="/animais/novo"><Plus size={15}/> Cadastrar animal</Link></Button></div></div>{visibilityError&&<p className="settings-error" role="alert">{visibilityError}</p>}<div className="my-pets-grid">{pets.map((pet)=><article className="my-pet-card" key={pet.id}><div className="my-pet-photo" style={pet.coverPhotoUrl?{backgroundImage:`url(${pet.coverPhotoUrl})`}:{}}><PawPrint size={25}/><span className={pet.isPublic?"pet-public":"pet-private"}>{pet.isPublic?"Visível":"Privado"}</span></div><div className="my-pet-copy"><h2><Link href={`/pet/perfil?petId=${encodeURIComponent(pet.id)}`}>{pet.name}<ArrowUpRight size={16}/></Link></h2><p>{pet.breed||pet.speciesOther||pet.species}</p><span>{pet.intent==="ADOPTION"?"Adoção":pet.intent==="RESPONSIBLE_BREEDING"?"Relacionamento":"Amizade"}</span><button className="pet-visibility-toggle" disabled={visibilityBusy===pet.id} onClick={()=>void toggleVisibility(pet)}>{visibilityBusy===pet.id?<LoaderCircle size={13}/>:null}{pet.isPublic?"Tornar privado":"Publicar perfil"}</button></div><PetPhotosManager key={`${pet.id}:${(pet.photos ?? []).map((photo)=>photo.storageKey).join(",")}`} petId={pet.id} initialPhotos={pet.photos ?? []} onSaved={()=>void refreshPets()}/></article>)}</div><div className="collection-footnote"><ShieldCheck size={14}/> Endereço residencial nunca aparece nos perfis públicos.</div></div>;
  return <div className="empty-collection"><div className="empty-collection-art"><div><PawPrint size={30}/></div><span>✦</span><i>♥</i></div><div className="product-eyebrow"><span><PawPrint size={13}/></span> SEU TIME DE QUATRO PATAS</div><h1 className="product-h1">Todo bom encontro<br/>começa <em>por aqui.</em></h1><p className="product-lead">Cadastre os animais que fazem parte da sua vida. Você controla quais perfis ficam visíveis e para que tipo de conexão.</p><Button asChild><Link href="/animais/novo"><Plus size={16}/> Cadastrar um animal</Link></Button><div className="collection-footnote"><ShieldCheck size={14}/> Endereço residencial nunca aparece nos perfis públicos.</div></div>;
}

export function SimpleEmptyView({ kind }: { kind: "matches"|"messages"|"community"|"settings"|"notifications" }) {
  const content = {
    matches:{icon:<Heart size={25}/>, kicker:"CONEXÕES COM INTERESSE MÚTUO", title:<>Os bons encontros<br/><em>começam aqui.</em></>, text:"Quando os dois tutores demonstram interesse, vocês podem se conhecer melhor por aqui.", action:"Explorar perfis", href:"/explorar"},
    messages:{icon:<MessageCircle size={25}/>, kicker:"CONVERSAS PRIVADAS", title:<>Uma boa conversa<br/><em>pode começar.</em></>, text:"As mensagens ficam disponíveis depois de um match. Combine sempre um encontro seguro.", action:"Ver meus matches", href:"/matches"},
    community:{icon:<PawPrint size={25}/>, kicker:"COMUNIDADE MATCHANIMAL", title:<>Histórias que<br/><em>aproximam.</em></>, text:"Em breve, um espaço para compartilhar momentos, dicas e boas histórias com outros tutores.", action:"Descobrir pets", href:"/explorar"},
    settings:{icon:<Settings2 size={25}/>, kicker:"PRIVACIDADE E PREFERÊNCIAS", title:<>Você no controle<br/><em>da sua conta.</em></>, text:"Em breve, você poderá ajustar privacidade, notificações e preferências da sua conta neste espaço.", action:"Voltar ao início", href:"/dashboard"},
    notifications:{icon:<Bell size={25}/>, kicker:"ATUALIZAÇÕES", title:<>Boas notícias<br/><em>por aqui.</em></>, text:"Quando houver novas interações, avisaremos você neste espaço.", action:"Explorar perfis", href:"/explorar"},
  }[kind];
  return <div className="empty-collection"><div className="empty-collection-art"><div>{content.icon}</div><span>✦</span><i>♥</i></div><div className="product-eyebrow"><span><Sparkles size={13}/></span>{content.kicker}</div><h1 className="product-h1">{content.title}</h1><p className="product-lead">{content.text}</p><Button variant="outline" asChild><Link href={content.href}>{content.action}<ArrowRight size={15}/></Link></Button></div>;
}

