"use client";

import { useCallback, useEffect, useState, type FormEvent } from "react";
import { Check, LoaderCircle, Save, ShieldCheck } from "lucide-react";
import { LocationPicker, type LocationSelection } from "@/components/location-picker";

type Account = { email: string; tutor: { displayName: string; city: string | null; state: string | null; latitude: number | null; longitude: number | null; isPublic: boolean; notificationOptIn: boolean } };
const api = process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:4000";

export function SettingsView() {
  const [account, setAccount] = useState<Account | null>(null);
  const [location, setLocation] = useState<LocationSelection | null>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [saved, setSaved] = useState(false);
  const [loading, setLoading] = useState(true);
  const load = useCallback(async () => {
    setLoading(true); setError("");
    try {
      const response = await fetch(`${api}/api/auth/me`, { credentials: "include" });
      if (!response.ok) throw new Error("Não foi possível carregar sua conta. Tente novamente.");
      setAccount(await response.json() as Account);
    } catch (cause) { setError(cause instanceof Error ? cause.message : "Não foi possível carregar sua conta."); }
    finally { setLoading(false); }
  }, []);
  useEffect(() => { void load(); }, [load]);
  async function save(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); if (!account || busy) return;
    setBusy(true); setSaved(false); setError("");
    const form = new FormData(event.currentTarget);
    const payload = { displayName: String(form.get("displayName") ?? ""), city: location?.city ?? account.tutor.city, state: location?.state ?? account.tutor.state, ...(location ? { latitude: location.latitude, longitude: location.longitude } : {}), publicProfile: form.get("publicProfile") === "on", notificationsEnabled: form.get("notificationsEnabled") === "on" };
    try { const response = await fetch(`${api}/api/auth/me`, { method: "PATCH", credentials: "include", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) }); const result = await response.json(); if (!response.ok) throw new Error(Array.isArray(result.message) ? result.message.join(" ") : result.message ?? "Não foi possível salvar as configurações."); setAccount({ ...account, tutor: { ...account.tutor, ...result } }); window.dispatchEvent(new CustomEvent("matchanimal:profile-updated", { detail: { displayName: payload.displayName, city: payload.city, state: payload.state } })); setLocation(null); setSaved(true); }
    catch (cause) { setError((cause as Error).message); } finally { setBusy(false); }
  }
  if (loading) return <div className="profile-loading" role="status"><span className="session-spinner"/> Carregando configurações…</div>;
  if (!account) return <div className="ma-flow-error" role="alert"><ShieldCheck size={28}/><h1>Suas configurações não carregaram</h1><p>{error}</p><button type="button" onClick={() => void load()}>Tentar novamente</button></div>;
  return <form className="settings-view" onSubmit={(event) => void save(event)}><header><div className="product-eyebrow"><span><ShieldCheck size={13}/></span> CONTA, PRIVACIDADE E PREFERÊNCIAS</div><h1 className="product-h1">Suas escolhas, <em>no seu controle.</em></h1><p className="product-lead">Atualize seu perfil e decida como o MatchAnimal pode usar suas informações.</p></header><section className="settings-card"><h2>Perfil do tutor</h2><label>Nome para exibição<input name="displayName" defaultValue={account.tutor.displayName} minLength={2} maxLength={80} required/></label><label>E-mail da conta<input value={account.email} readOnly disabled/></label><div className="settings-location"><h3>Região aproximada</h3><p>Usamos a cidade para descobrir animais próximos. Seu endereço residencial não é publicado.</p><LocationPicker initial={{ city: account.tutor.city ?? undefined, state: account.tutor.state ?? undefined, latitude: account.tutor.latitude ?? undefined, longitude: account.tutor.longitude ?? undefined }} onSelect={setLocation}/></div></section><section className="settings-card"><h2>Privacidade e avisos</h2><label className="settings-toggle"><span><strong>Perfil do tutor público</strong><small>Permite que outras pessoas vejam seu nome e sua região em interações sociais.</small></span><input type="checkbox" name="publicProfile" defaultChecked={account.tutor.isPublic}/></label><label className="settings-toggle"><span><strong>Notificações no MatchAnimal</strong><small>Receba avisos sobre interesses, matches e novos seguidores.</small></span><input type="checkbox" name="notificationsEnabled" defaultChecked={account.tutor.notificationOptIn}/></label><p className="settings-note"><ShieldCheck size={15}/> Os perfis dos seus animais continuam com controles próprios de visibilidade.</p></section>{error && <p className="settings-error" role="alert">{error}</p>}{saved && <p className="settings-saved" role="status"><Check size={15}/> Configurações salvas.</p>}<button className="settings-save" type="submit" disabled={busy}>{busy?<LoaderCircle className="settings-spin" size={16}/>:<Save size={16}/>} Salvar alterações</button></form>;
}

