"use client";
import { useEffect, useState } from "react";
import { LoaderCircle, PawPrint } from "lucide-react";
import { PostCard, type FeedPost } from "@/components/community-feed";
const api = process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:4000";
export function SharedPost({ postId }: { postId: string }) {
  const [post, setPost] = useState<FeedPost | null>(null); const [error, setError] = useState("");
  const load = async () => { try { const response = await fetch(`${api}/api/community/posts/${postId}`, { credentials: "include" }); if (!response.ok) throw new Error("Esta publicação não está disponível para sua conta."); setPost(await response.json()); } catch (reason) { setError((reason as Error).message); } };
  async function like() { await fetch(`${api}/api/community/posts/${postId}/like`, { method: "POST", credentials: "include" }); await load(); }
  async function save() { await fetch(`${api}/api/community/posts/${postId}/save`, { method: "POST", credentials: "include" }); await load(); }
  useEffect(() => { void load(); }, [postId]);
  if (!post && !error) return <div className="community-state"><LoaderCircle className="community-spin"/> Carregando publicação…</div>;
  if (!post) return <div className="community-empty"><span><PawPrint size={23}/></span><h2>Publicação indisponível</h2><p>{error}</p></div>;
  return <div className="shared-post-page"><a href="/comunidade" className="community-back-link">← Voltar à comunidade</a><PostCard post={post} onLike={() => void like()} onSave={() => void save()} onReport={() => { const reason = window.prompt("Conte por que você está denunciando esta publicação."); if (reason) void fetch(`${api}/api/safety/reports`, { method: "POST", credentials: "include", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ targetType: "POST", targetId: post.id, reason }) }); }} onChanged={() => void load()}/></div>;
}

